// Gabarito comentado — administrativo (gerado). Chave: chaveQ(enunciado) em leitura/index.js.
export default {"agentes":{"uu10q2":["É o art. 37, III, da CF: até dois anos, prorrogável uma vez por igual período. A prorrogação é ato discricionário e deve ocorrer antes de expirar o prazo inicial.",""],"5li2f5":["O retorno do servidor demitido, quando a demissão é anulada, é a REINTEGRAÇÃO (Lei 8.112, art. 28). REVERSÃO é o retorno do APOSENTADO à atividade (art. 25).","Macete: Reintegração = demitido que volta. Reversão = aposentado que volta. Recondução = volta ao cargo anterior. Aproveitamento = volta de quem estava em disponibilidade."],"1ev2p3b":["No Tema 161 (RE 598.099), o STF fixou o direito subjetivo à nomeação do aprovado dentro das vagas do edital, salvo situações excepcionais, supervenientes, imprevisíveis, graves e necessárias, devidamente motivadas.",""],"1w3fly6":["É o art. 37, XVI, b, da CF. As outras hipóteses são dois cargos de professor e dois cargos privativos de profissionais de saúde com profissão regulamentada, sempre com compatibilidade de horários.",""],"muuk77":["O retorno de quem está em disponibilidade é o APROVEITAMENTO (art. 30). Reversão é o retorno do aposentado (art. 25).",""],"b8tvz8":["É o art. 142, III. Prescrição: 5 anos (demissão, cassação e destituição), 2 anos (suspensão) e 180 dias (advertência), contados da data em que o fato se tornou conhecido.",""],"1059xpg":["As instâncias são independentes. Só a absolvição penal que NEGA o fato ou a autoria afasta a responsabilidade administrativa (Lei 8.112, art. 126). Absolvição por falta de provas não impede a punição disciplinar.",""],"rqgk9a":["É o art. 149 da Lei 8.112: três servidores estáveis, e o presidente deve ocupar cargo efetivo superior ou de mesmo nível, ou ter escolaridade igual ou superior à do indiciado.",""],"d79vnw":["Agentes políticos compõem a cúpula do Estado e exercem funções previstas na Constituição: Chefes do Executivo e seus auxiliares (ministros e secretários), parlamentares e, para parte da doutrina, magistrados e membros do MP.",""],"1jtzc8u":["Agentes administrativos têm vínculo profissional com o Estado: estatutários (cargo), empregados públicos (emprego, CLT) e temporários (art. 37, IX).",""],"1pmk763":["Particulares em colaboração exercem função pública sem perder a condição de particulares. Os honoríficos (requisitados) são mesários, jurados e convocados para o serviço militar; há ainda os delegados (concessionários, cartorários) e os voluntários.",""],"1yrcf1l":["É o art. 3º, parágrafo único, da Lei 8.112. Só lei cria cargo, salvo na estrutura do Legislativo, em que a criação se faz por resolução.",""],"1ouy7vw":["O emprego público é regido pela CLT e existe nas empresas públicas e sociedades de economia mista (e, após a ADI 2.135, pode existir também na administração direta).",""],"39gd0f":["É o art. 37, II, da CF, ressalvados os cargos em comissão declarados em lei de livre nomeação e exoneração.",""],"qnd7yf":["Tema 161 do STF.",""],"1ja9bot":["É o Tema 784 do STF: o aprovado fora das vagas só tem direito à nomeação se houver preterição arbitrária e imotivada, como contratar temporários para as mesmas funções ou nomear fora da ordem.",""],"vp0wo":["É a Súmula Vinculante 44. O psicotécnico também deve ter critérios objetivos e permitir recurso.",""],"1dlic06":["É a Súmula Vinculante 43: acabou a ascensão e a transferência para outra carreira sem concurso.",""],"1sxnf4x":["É o art. 13, §1º, da Lei 8.112. Se não houver posse no prazo, o ato de provimento é tornado sem efeito.",""],"1gkba6c":["É o art. 15, §1º, da Lei 8.112. Quem não entra em exercício é exonerado.","Posse = 30 dias da publicação. Exercício = 15 dias da posse."],"71y49n":["É o art. 8º da Lei 8.112. A nomeação é a única forma de provimento originário; as demais são derivadas.",""],"jdqe0w":["É o art. 25 da Lei 8.112: de ofício, quando cessam os motivos da aposentadoria por invalidez, ou a pedido, no interesse da Administração, em certas condições.",""],"ovomsq":["É o art. 28 da Lei 8.112: o servidor volta ao cargo de origem com ressarcimento de todas as vantagens. Se o cargo foi extinto, fica em disponibilidade.",""],"1v4guj7":["É o art. 29 da Lei 8.112: por inabilitação em estágio probatório de outro cargo ou por reintegração do anterior ocupante. O STF admite também a recondução por desistência do estágio probatório.",""],"1oycnpz":["É o art. 30 da Lei 8.112: o retorno é obrigatório, em cargo de atribuições e vencimentos compatíveis com o anterior.",""],"wbmncf":["É o art. 24 da Lei 8.112: a limitação é verificada em inspeção médica, e o novo cargo deve ter atribuições afins, mesma escolaridade e equivalência de vencimentos.",""],"o5fnkh":["A ascensão e a transferência foram retiradas da Lei 8.112 (Lei 9.527/1997), e a SV 43 proíbe investir servidor, sem concurso, em cargo de outra carreira.",""],"t3sc7o":["É o art. 33 da Lei 8.112. Promoção e readaptação são ao mesmo tempo forma de provimento (do novo cargo) e de vacância (do anterior).",""],"ix7clg":["Demissão é penalidade aplicada após PAD (art. 132). Exoneração é desligamento sem caráter punitivo: a pedido ou de ofício (não aprovação no estágio, não entrar em exercício, cargo em comissão).",""],"1b3gzo1":["É o art. 127: advertência, suspensão, demissão, cassação de aposentadoria ou disponibilidade, destituição de cargo em comissão e destituição de função comissionada.",""],"q3tgqv":["É o art. 130 da Lei 8.112. Por conveniência do serviço, a suspensão pode ser convertida em multa de 50% por dia de remuneração (§2º).",""],"l1m0v9":["É o art. 142 da Lei 8.112. A abertura de sindicância ou do PAD interrompe a prescrição.",""],"13dmdf1":["É o art. 145 da Lei 8.112. Penalidade mais grave (suspensão acima de 30 dias, demissão) exige PAD (art. 146).",""],"1m3rsc3":["É o art. 149 da Lei 8.112.",""],"1kmzxo4":["É o art. 152 da Lei 8.112: 60 dias, prorrogáveis por igual prazo. O julgamento é feito em 20 dias do recebimento (art. 167).",""],"7e3r8d":["É o art. 147 da Lei 8.112: até 60 dias, prorrogável por igual prazo, sem prejuízo da remuneração.",""],"1oatna5":["É a Súmula Vinculante 5.",""],"qsnv1j":["É o art. 125 da Lei 8.112: as sanções podem cumular-se.",""],"tdx5nx":["É o art. 126 da Lei 8.112: a negativa do fato ou da autoria no juízo criminal repercute na esfera administrativa.",""],"u51zj6":["Lei 8.112, art. 25: reversão.","",["Reintegração é a volta do demitido.","Recondução é a volta ao cargo anterior.","Correta.","Readaptação é a mudança por limitação de saúde.","Aproveitamento é a volta de quem estava em disponibilidade."]],"1jrct9v":["Lei 8.112, art. 30: aproveitamento.","",["Reversão é a volta do aposentado.","Correta.","Recondução é a volta ao cargo anterior.","Reintegração é a volta do demitido.","Promoção é a progressão na carreira."]],"oryoti":["Art. 13, §1º: 30 dias.","",["15 dias é o prazo do exercício.","Correta.","45 dias não é o prazo.","60 dias não é o prazo.","90 dias não é o prazo."]],"1nxd4vs":["Art. 130: 90 dias.","",["30 dias é o limite da sindicância.","60 dias é o prazo do PAD.","Correta.","120 dias não é o limite.","180 dias é a prescrição da advertência."]],"nlgujl":["Art. 142, II: 2 anos.","",["180 dias é a advertência.","1 ano não é o prazo.","Correta.","3 anos não é o prazo.","5 anos é a demissão."]],"1f9ddhq":["Art. 149: três servidores estáveis.","",["Um só não basta.","Dois não bastam.","Correta.","Cinco não é o número.","Não se exige advogado."]],"dg29uw":["Art. 145, II: 30 dias.","",["10 dias não é o limite.","15 dias não é o limite.","Correta.","60 dias exige PAD.","90 dias é o máximo geral da suspensão, que exige PAD acima de 30."]],"pxxgbo":["Art. 8º: nomeação, promoção, readaptação, reversão, aproveitamento, reintegração e recondução.","",["É forma de provimento.","É forma de provimento.","Correta: a transferência foi suprimida.","É forma de provimento.","É forma de provimento."]],"42c9eu":["Art. 126: nega a existência do fato ou a autoria.","",["Falta de provas não repercute.","Correta.","A prescrição penal não repercute.","O perdão judicial não repercute.","A insignificância penal não impede punição disciplinar."]],"1ib95fn":["Particular em colaboração, na modalidade honorífica (requisitado).","",["Não é agente político.","Não é estatutário.","Correta.","Não é empregado público.","Não é temporário do art. 37, IX."]],"op1ws0":["Tema 161: direito subjetivo.","",["Não é mera expectativa.","Correta.","Não é faculdade.","Não é proibida.","Não depende de lei específica."]]},"atos":{"246gpu":["Revogar é retirar um ato válido por não ser mais conveniente ou oportuno. Só quem praticou o ato (a Administração) pode avaliar o mérito, e os efeitos valem dali para frente (ex nunc), respeitando os direitos adquiridos.","O Judiciário pode revogar os seus próprios atos administrativos, mas nunca os do Executivo."],"1u4ynf9":["Em regra, convalidam-se só os vícios de competência (se não exclusiva) e de forma (se não essencial). Vícios de finalidade, motivo e objeto são insanáveis e levam à anulação.","Macete \"FOCO\" no sanável: FOrma e COmpetência. Finalidade, motivo e objeto, não."],"1jeqhmr":["Se a Administração declara um motivo, o ato só é válido se esse motivo for verdadeiro e existente. Motivo falso ou inexistente torna o ato nulo, mesmo que a motivação fosse dispensável.",""],"1gto9nl":["É a regra doutrinária, com base no art. 55 da Lei 9.784/1999: defeitos sanáveis podem ser convalidados se não lesarem o interesse público nem terceiros.",""],"13814sy":["A imperatividade (impor obrigações sem concordância do particular) não existe nos atos negociais (licença, autorização) nem nos enunciativos (certidão, parecer). Atributo de todos os atos é só a presunção de legitimidade.",""],"1wzqg8k":["Exemplo clássico: a exoneração de cargo em comissão dispensa motivação, mas, se a autoridade escreve \"por corte de gastos\" e nomeia outro no dia seguinte, o ato é nulo.",""],"1ehpyxa":["O Judiciário faz controle de LEGALIDADE: pode ANULAR atos ilegais. A revogação, por conveniência e oportunidade, é exclusiva de quem praticou o ato.",""],"yiloys":["Na licença, preenchidos os requisitos, a Administração é obrigada a conceder (exemplo: licença para construir). Na autorização, há discricionariedade e precariedade (exemplo: autorização para uso de bem público em evento).",""],"o8g81h":["É a classificação baseada no art. 2º da Lei 4.717/1965 (Lei da Ação Popular).",""],"tsh91m":["A lei define quem pratica o ato, para qual fim e de que forma. Motivo e objeto podem ser discricionários e formam o mérito administrativo.",""],"tms2p3":["O mérito é a margem de escolha do administrador sobre motivo (quando agir) e objeto (o que decidir). O Judiciário não controla o mérito, salvo por razoabilidade e proporcionalidade.",""],"1hntuf9":["É o art. 11 da Lei 9.784/1999. Não podem ser delegados os atos normativos, a decisão de recursos administrativos e as matérias de competência exclusiva (art. 13).",""],"7muzs":["O desvio de finalidade (praticar o ato para fim diferente do previsto em lei) é vício insanável.",""],"1m6jkaq":["Exemplo: ato praticado por subordinado sem delegação pode ser ratificado pela autoridade competente, se a competência não for exclusiva.",""],"1nvd3oz":["Exemplo: falha formal menor pode ser suprida; mas se a lei exige forma como requisito de validade (decreto, por exemplo), não há convalidação.",""],"1nt3z7c":["É o art. 55: sem lesão ao interesse público nem prejuízo a terceiros, a Administração pode convalidar.",""],"1gg9gq3":["O motivo é o pressuposto do ato (exemplo: a infração cometida é o motivo da multa).",""],"5sopt2":["A motivação é a explicação dos motivos e integra a forma do ato. Motivo é o fato; motivação é a explicação dele.",""],"fyvdln":["Motivo declarado falso ou inexistente invalida o ato.",""],"1yoxrkl":["É o exemplo clássico da teoria dos motivos determinantes.",""],"1gy82os":["É o art. 50, I. O art. 50 também exige motivação para atos que imponham deveres, decidam processos, dispensem licitação, decidam recursos, entre outros.",""],"16y9hsh":["Todo ato se presume legal e com fatos verdadeiros até prova em contrário (presunção relativa, juris tantum). O ônus de provar o vício é de quem alega.",""],"1y19586":["É o chamado poder extroverso: a Administração cria obrigações para o particular de forma unilateral, como numa ordem de demolição.",""],"bicl5u":["Os atos negociais atendem a pedido do particular e não impõem obrigação. Neles não há imperatividade.",""],"15wcnnk":["A autoexecutoriedade permite executar o ato sem ordem judicial. Não existe em todos os atos: só quando a lei autoriza ou em urgência. A cobrança de multa, por exemplo, depende de execução judicial.",""],"w0tv1b":["É atributo apontado por Maria Sylvia Di Pietro: para cada finalidade, há um tipo de ato previsto em lei, o que protege o particular contra atos inominados.",""],"1gijk8s":["No ato complexo, as vontades se fundem e formam um ato só, que só existe depois da última manifestação. Exemplo: aposentadoria (para parte da doutrina) e nomeação de dirigentes com aprovação do Senado.",""],"3pqjyu":["No ato composto há um ato principal e outro acessório (visto, homologação ou aprovação). Exemplo: ato que depende do visto da autoridade superior.",""],"1x03ybx":["Preenchidos os requisitos legais, a licença deve ser concedida e não pode ser revogada por conveniência.",""],"1v08hh3":["A autorização pode ser concedida ou não, e revogada a qualquer tempo, em regra sem indenização.",""],"19dkww":["Atos enunciativos declaram ou certificam uma situação, ou emitem opinião, sem criar obrigação.",""],"uqkcaz":["A anulação retira o ato ilegal desde a origem (ex tunc). Pode ser feita pela Administração (autotutela, Súmula 473) ou pelo Judiciário. A Administração tem 5 anos para anular atos que favorecem o particular de boa-fé (Lei 9.784, art. 54).",""],"1oqcnie":["Só pela Administração que praticou o ato.",""],"1hodrvq":["O Judiciário só anula atos ilegais. Revogação é exclusiva da própria Administração.",""],"1378p56":["São os limites da revogação. Também não se revogam os atos enunciativos e os que integram um procedimento já concluído.",""],"1kz1w6f":["Exemplo: alvará de hotel cassado porque o local virou casa de jogos.",""],"14ye1j5":["Exemplo: permissão para circo em terreno que uma lei nova transformou em área residencial.",""],"bc5ggm":["Exemplo: a exoneração extingue os efeitos da nomeação. Também se chama derrubada.",""],"pgwf9x":["Pela doutrina, o silêncio é fato jurídico administrativo, e não ato. Só produz efeito (deferimento ou indeferimento tácito) quando a lei prevê.",""],"12icp3s":["A finalidade é o interesse público que o ato busca.","",["A competência responde a \"quem?\".","Correta.","A forma responde a \"como?\".","O motivo responde a \"por quê?\".","O objeto responde a \"o quê?\"."]],"yrlu64":["Finalidade (desvio de poder) é vício insanável.","",["Admite convalidação.","Admite convalidação.","Correta.","Nem todos admitem.","Alguns admitem."]],"e0hanb":["Presunção de legitimidade.","",["Falta nos atos negociais e enunciativos.","Depende de lei ou urgência.","Correta.","A tipicidade é de todos para parte da doutrina, mas a alternativa é restritiva.","Coercibilidade não é atributo de todos."]],"47xkod":["Ex nunc (para o futuro).","",["Ex tunc é a anulação.","Correta.","Não há repristinação automática.","Produz efeitos jurídicos.","Não é retroativa."]],"1jfm08m":["Cassação: descumprimento das condições pelo beneficiário.","",["Revogação é por conveniência.","Anulação é por ilegalidade do próprio ato.","Correta.","Caducidade é por lei nova.","Contraposição é por ato de efeito oposto."]],"q4tw50":["Ato complexo, para a doutrina tradicional: as vontades de dois órgãos se fundem num ato.","",["Simples tem uma só manifestação.","Correta.","Composto tem ato principal e acessório.","Enunciativo declara ou opina.","Negocial atende a pedido do particular."]],"1w8lo20":["Vinculado e definitivo.","",["Essa é a autorização.","Correta.","Enunciativo é certidão e parecer.","Normativo é regulamento.","Punitivo é multa."]],"wa2vmy":["O motivo declarado vincula a validade do ato.","",["Todo ato tem motivo.","Correta.","Quem motiva é a própria Administração.","O motivo não pode ser trocado depois.","O ato vinculado também tem motivo."]],"13243jw":["O ato vinculado não tem mérito para reavaliar.","",["Pode ser revogado.","Correta.","Pode ser revogada.","Pode ser revogada.","Pode ser revogado (dispensa)."]],"1046dd5":["Caducidade.","",["Cassação é por descumprimento.","Correta.","Anulação é por ilegalidade original.","Revogação é por conveniência.","Convalidação corrige, não extingue."]],"m234ys":["Enunciativo (opinativo).","",["Não é normativo.","Ordinatório organiza o serviço interno.","Correta.","Não é punitivo.","Não é negocial."]],"k77pwr":["Art. 55: defeito sanável, sem lesão ao interesse público nem prejuízo a terceiros.","",["Desvio de finalidade é insanável.","Correta.","Ato inexistente não se convalida.","Má-fé impede.","Objeto ilícito é insanável."]]},"bens-intervencao":{"1pursdy":["É o art. 5º, XXV, da CF: em perigo público iminente, a autoridade usa o bem particular (imóvel, móvel ou serviço) e só indeniza depois, se houver dano. Exemplo: requisitar hotel para abrigar desabrigados de enchente.",""],"iy5zi3":["Todos os bens públicos são imprescritíveis, inclusive os dominicais (CC, art. 102; Súmula 340 do STF; CF, arts. 183, §3º, e 191). Não importa se estão afetados ou não.","Dominical pode ser vendido (alienável, com requisitos), mas não pode ser usucapido."],"gg0qkl":["É o art. 184 da CF: só a União desapropria para reforma agrária, pagando a terra nua em títulos da dívida agrária resgatáveis em até 20 anos.",""],"1dhl4a7":["A imprescritibilidade alcança todos os bens públicos.",""],"1r639kv":["Na requisição a indenização é ULTERIOR e só existe se houver dano (art. 5º, XXV). Indenização prévia é característica da desapropriação.",""],"14ouske":["É o art. 243 da CF (expropriação-confisco): o imóvel com cultivo ilegal de psicotrópicos ou trabalho escravo é destinado à reforma agrária e à habitação popular, sem indenização. Para o STF, basta a culpa do proprietário, ainda que in vigilando (Tema 399).",""],"qdtsur":["A limitação é geral e abstrata (atinge todos os imóveis numa mesma situação, como recuo obrigatório e gabarito de altura) e, em regra, não gera indenização. Quem atinge imóvel determinado é a servidão.",""],"kyjo6z":["Tredestinação ilícita é dar ao bem desapropriado um destino sem interesse público (exemplo: entregar a um particular para fins privados). Ela dá ao antigo dono o direito à retrocessão ou a perdas e danos. A tredestinação lícita (outro fim público) não gera esse direito.",""],"jwro81":["É o art. 99, I, do Código Civil: bens usados por todos, em regra gratuitamente.",""],"c9rtdn":["É o art. 99, II, do CC: prédios de repartições, escolas, hospitais e veículos oficiais.",""],"1te5xba":["É o art. 99, III, do CC: bens sem destinação pública específica (terras devolutas, imóveis desocupados), que podem ser alienados.",""],"1hypj6d":["É o art. 100 do CC: a inalienabilidade é relativa e acaba com a desafetação.",""],"11p86h7":["É o art. 101 do CC: interesse público, avaliação prévia, licitação e, para imóveis, autorização legislativa (Lei 14.133, art. 76).",""],"1xmjum9":["É o art. 102 do CC e os arts. 183, §3º, e 191, parágrafo único, da CF.",""],"1xrhnnr":["Também os dominicais são imprescritíveis (Súmula 340 do STF).",""],"adu1pi":["Os bens públicos não podem ser penhorados. As dívidas judiciais da Fazenda são pagas por precatório ou RPV (CF, art. 100).",""],"17nz2uv":["Afetar é dar destino público (transformar um terreno em escola); desafetar é retirar esse destino, por lei, ato administrativo ou fato (como um incêndio que destrói o prédio).",""],"wdx0np":["É o art. 76, I, da Lei 14.133/2021: interesse público justificado, avaliação prévia, autorização legislativa e licitação na modalidade leilão, salvo as dispensas previstas.",""],"13z9jg3":["O STF reconheceu aos Correios a impenhorabilidade dos bens e o pagamento por precatório (RE 220.906), por prestarem serviço público em regime de exclusividade.",""],"4cn52f":["A autorização atende ao interesse do particular, como fechar uma rua para festa junina, e pode ser revogada a qualquer tempo.",""],"1tk7b00":["A concessão de uso é contratual, mais estável, normalmente com prazo, e exige licitação, em regra. Exemplo: lanchonete num aeroporto.","Autorização e permissão são atos unilaterais; a concessão é contrato."],"1dafxjk":["Ela atinge uma coletividade indeterminada de imóveis e não gera indenização, salvo se esvaziar o conteúdo econômico da propriedade.",""],"vj01e7":["A servidão incide sobre imóvel determinado (linha de transmissão, placa de rua, aqueduto). A indenização só é devida se houver prejuízo efetivo.",""],"pctij6":["É o art. 5º, XXV, da CF.",""],"9bpulf":["É o art. 36 do DL 3.365/1941: o poder público usa terreno vizinho para guardar máquinas e materiais da obra, com indenização.",""],"1mhnl1f":["É o DL 25/1937 e o art. 216, §1º, da CF. O tombamento pode alcançar bens públicos e privados, móveis e imóveis.",""],"8otapu":["É o art. 5º, XXIV, da CF, nas hipóteses de necessidade ou utilidade pública ou interesse social.",""],"1ofuid7":["É o art. 182, §4º, III, da CF: títulos resgatáveis em até 10 anos, para o imóvel urbano que não cumpre a função social mesmo após parcelamento compulsório e IPTU progressivo.",""],"1ujawfe":["É o art. 184 da CF.",""],"1b4i7jw":["É o art. 184, §1º, da CF. As benfeitorias voluptuárias seguem o pagamento em títulos.",""],"1r0veoo":["É o art. 243 da CF (redação da EC 81/2014).",""],"1r97h8r":["É o art. 10 do DL 3.365/1941. Depois de caducar, só se pode fazer nova declaração passado um ano.",""],"1prdlb4":["É o art. 3º da Lei 4.132/1962.","Utilidade ou necessidade pública = 5 anos. Interesse social = 2 anos."],"1ijfjkz":["É o art. 15 do DL 3.365/1941: o expropriante alega urgência e deposita o valor fixado, e o juiz o imite na posse antes do fim do processo. A urgência deve ser requerida em até 120 dias.",""],"zqdgyz":["É o art. 20 do DL 3.365/1941. Qualquer outra questão (como desvio de finalidade) deve ser discutida em ação própria.",""],"l7dihw":["O Estado ocupa o bem sem desapropriar formalmente. O proprietário não pode reaver o bem já afetado, mas tem direito a indenização por ação própria.",""],"1afkw9f":["É o entendimento da doutrina e da jurisprudência, com base no art. 519 do Código Civil.",""],"70p1ne":["Se a parte que sobrou ficou inútil ou de difícil aproveitamento, o dono pode exigir que ela também seja desapropriada e indenizada.",""],"15r9jhs":["A desapropriação para reforma agrária é exclusiva da União (art. 184). O Município pode desapropriar imóvel rural por utilidade pública ou interesse social comum, mas não para reforma agrária.",""],"11welrc":["CC, art. 99, I: de uso comum do povo.","",["Dominical não tem destinação.","De uso especial é o destinado a serviço público.","Correta.","É bem público.","Está afetada ao uso coletivo."]],"13ojimg":["CC, art. 99, II: de uso especial.","",["Não é de uso comum.","Correta.","Não é dominical.","É público.","É inalienável enquanto afetado."]],"1jpjvz2":["CC, art. 99, III: dominical.","",["Não é de uso comum.","Não é de uso especial.","Correta.","Pode ser alienado.","É público."]],"ar0dl5":["Requisição administrativa (art. 5º, XXV).","",["A servidão é permanente e sobre imóvel determinado.","Correta.","O tombamento protege o patrimônio cultural.","A limitação é geral.","A desapropriação tira a propriedade."]],"mp4v6y":["Limitação administrativa: geral e abstrata.","",["A servidão é sobre imóvel determinado.","Correta.","A requisição é para perigo público.","A ocupação temporária é transitória.","Não há apossamento."]],"1btzzvj":["Servidão administrativa: direito real sobre imóvel determinado.","",["A limitação é geral.","Correta.","O tombamento protege o patrimônio cultural.","A requisição é transitória.","Confisco é sem indenização, por ilícito."]],"1utevdc":["CF, art. 184: títulos da dívida agrária.","",["Em dinheiro, só as benfeitorias úteis e necessárias.","Os títulos são agrários e federais.","Correta.","Não é precatório comum.","Há indenização."]],"1tj2sro":["DL 3.365, art. 10: 5 anos.","",["1 ano é o prazo para renovar a declaração após a caducidade.","2 anos é o do interesse social.","3 anos não é o prazo.","Correta.","10 anos não é o prazo."]],"1j9xfk6":["CF, art. 243: não gera indenização.","",["Não é paga em dinheiro.","Não é paga em títulos.","Correta.","Não depende de acordo.","É prevista na CF."]],"7enw7c":["DL 3.365, art. 20: vício do processo ou impugnação do preço.","",["Não é qualquer matéria.","Correta.","A utilidade pública não pode ser discutida ali.","A posse não é o tema.","Pode tratar dessas duas."]],"16tr5fl":["CC, art. 102: imprescritibilidade.","",["Inalienabilidade impede a venda.","Correta.","Impenhorabilidade impede a penhora.","Não onerabilidade impede dar em garantia.","Afetação é a destinação pública."]],"e1mtwn":["Retrocessão.","",["Tredestinação é o desvio em si.","Correta.","Direito de extensão é sobre a parte remanescente.","Requisição é outra intervenção.","Adestinação é não dar destino nenhum ao bem."]]},"conceito-principios":{"1t6gnv9":["Para a Administração vale a legalidade estrita: ela só age quando a lei autoriza ou determina. Para o particular é o contrário: pode fazer tudo o que a lei não proíbe (CF, art. 5º, II).",""],"1bi1mqg":["A SV 13 veda o nepotismo até o 3º grau (cônjuge, pais, filhos, avós, netos, irmãos, tios, sobrinhos, bisavós e bisnetos, e afins até o 3º grau). O primo é parente de 4º grau e não está na vedação.","Contagem colateral: irmão é 2º grau, tio e sobrinho 3º grau, primo 4º grau."],"1yrvahd":["É o art. 28 da LINDB (Lei 13.655/2018): o agente só responde pessoalmente por decisão ou opinião técnica se agir com dolo ou erro grosseiro. Erro comum, de boa-fé, não gera responsabilidade pessoal.",""],"1hnl25e":["Pelo critério da Administração Pública (Hely Lopes Meirelles), o Direito Administrativo é o conjunto de princípios e regras que rege órgãos, agentes e atividades públicas para realizar os fins do Estado de forma direta, concreta e imediata.",""],"1qyn3c8":["A publicidade é requisito de EFICÁCIA: o ato pode ser válido, mas só produz efeitos perante terceiros depois de publicado.",""],"vv3ql6":["O art. 2º da Lei 9.784/1999 lista legalidade, finalidade, motivação, razoabilidade, proporcionalidade, moralidade, ampla defesa, contraditório, segurança jurídica, interesse público e eficiência.",""],"6h5ndj":["A crítica ao critério do serviço público (Escola de Bordeaux) é justamente essa: ele deixa de fora atividades administrativas como o poder de polícia e o fomento.",""],"dx97a9":["É o conceito usual: o Direito Administrativo rege a função administrativa e quem a exerce (órgãos, entidades e agentes).",""],"1kg1pvn":["No sentido subjetivo (orgânico ou formal), Administração é QUEM exerce a função: órgãos, entidades e agentes. Costuma-se grafar com iniciais maiúsculas.",""],"1uk7lku":["No sentido objetivo (material ou funcional), administração é O QUE se faz: polícia administrativa, serviço público, fomento e intervenção.",""],"1lctkfq":["As atividades compõem o sentido OBJETIVO. O sentido subjetivo trata dos sujeitos: órgãos, entidades e agentes.",""],"4r7wu8":["A lei (em sentido amplo, incluindo a Constituição) é a fonte primária. Jurisprudência, doutrina e costumes são fontes secundárias. Súmulas vinculantes têm força obrigatória.",""],"1al37s4":["Para Celso Antônio Bandeira de Mello, essas são as \"pedras de toque\": a supremacia gera prerrogativas, e a indisponibilidade gera sujeições.",""],"1k6g2vp":["A Administração pode alterar e rescindir unilateralmente contratos, fiscalizar e aplicar sanções porque o interesse público prevalece sobre o particular.",""],"f5xizu":["Como o administrador não é dono do interesse público, ele se sujeita a regras como licitar, fazer concurso e prestar contas.",""],"v7n9ek":["Legalidade estrita (art. 37).",""],"lvsapa":["É o art. 37, §1º, da CF: a publicidade oficial não pode ter nomes, símbolos ou imagens que promovam autoridades.",""],"cljmz1":["Pela teoria do órgão (Otto Gierke), o ato do agente é atribuído ao Estado, e não à pessoa do agente. Por isso a publicidade deve divulgar o órgão, e não o nome de quem governa.",""],"136kl13":["A SV 13 alcança também o nepotismo cruzado: autoridade A nomeia parente de B, e B nomeia parente de A, em designações recíprocas.",""],"1a21e8m":["O limite é o 3º grau. O primo é parente de 4º grau.",""],"1tw7pvw":["O STF entende que a SV 13 não alcança, em regra, cargos políticos (ministros e secretários), salvo fraude, nepotismo cruzado ou falta evidente de qualificação técnica ou idoneidade (Rcl 6.650 e outras).",""],"qmd0rf":["É requisito de eficácia, e não de validade. Exceções ao dever de publicidade: segurança da sociedade e do Estado e intimidade (CF, art. 5º, XXXIII e LX).",""],"1qj8wrp":["A EC 19/1998 (Reforma Administrativa) incluiu a eficiência, completando o LIMPE.",""],"1wfhik1":["É a Súmula 473 do STF (e a 346): a Administração anula os atos ilegais e revoga os inconvenientes, respeitados os direitos adquiridos e ressalvada a apreciação judicial.",""],"7qbqmn":["Na CF são implícitos (decorrem do devido processo legal substantivo); na Lei 9.784, art. 2º, são expressos.",""],"eq5nac":["É o art. 54 da Lei 9.784/1999: 5 anos da data em que o ato foi praticado, salvo comprovada má-fé. Nos atos com efeitos patrimoniais contínuos, o prazo conta do primeiro pagamento.",""],"zasp2g":["O serviço público não pode parar. Por isso há restrições à greve em serviços essenciais, limites à exceção do contrato não cumprido e regras sobre corte de serviços.",""],"hhtb63":["É o art. 20 da LINDB: decisões administrativas, de controle e judiciais devem considerar as consequências práticas.",""],"n0gzon":["Art. 28 da LINDB: dolo ou erro grosseiro.",""],"1t4i66c":["É o art. 21 da LINDB: quem invalida deve dizer quais as consequências jurídicas e administrativas e, se for o caso, como regularizar de forma proporcional.",""],"vkzcgz":["É o art. 26 da LINDB: compromisso para eliminar irregularidade, incerteza jurídica ou situação contenciosa, inclusive na concessão de licença, ouvida a assessoria jurídica e, quando for o caso, após consulta pública.",""],"10gzdzm":["Não há hierarquia entre princípios: em caso de conflito, eles se ponderam no caso concreto.",""],"luz0w5":["É o art. 2º, parágrafo único, XIII, da Lei 9.784/1999: nova interpretação administrativa não retroage para prejudicar quem agiu conforme a anterior.",""],"1593hl1":["É a exigência do art. 50 da Lei 9.784/1999: a motivação deve ser explícita, clara e congruente, e pode remeter a pareceres anteriores (motivação aliunde, §1º).",""],"pp7jop":["A entidade criada para um fim (como uma autarquia de saúde) não pode passar a atuar em outra área, porque está presa à lei que a criou ou autorizou.",""],"1107ne3":["É a supervisão ministerial (controle finalístico): não há hierarquia, só controle do cumprimento das finalidades legais.",""],"6coedw":["É o critério mais adotado no Brasil para conceituar o Direito Administrativo.",""],"1ohrj6t":["O interesse público pertence à coletividade, e o administrador é só gestor. Por isso não pode renunciar a direitos, perdoar dívidas sem lei ou dispensar licitação fora das hipóteses legais.",""],"198mny5":["Moralidade (art. 37).","",["A legalidade exige atuar conforme a lei.","A impessoalidade veda favorecimentos e promoção pessoal.","Correta.","A publicidade exige transparência.","A eficiência exige bons resultados."]],"w7h152":["Autotutela.","",["Continuidade trata de serviços que não podem parar.","Correta.","Especialidade trata das finalidades das entidades.","Publicidade trata da transparência.","Hierarquia é a relação de subordinação."]],"r6bo9o":["Lei 9.784, art. 54: 5 anos.","",["1 ano não é o prazo.","2 anos não é o prazo.","3 anos não é o prazo.","Correta.","10 anos não é o prazo."]],"1f34hwm":["O caput traz o LIMPE: legalidade, impessoalidade, moralidade, publicidade e eficiência.","",["Está expresso.","Está expresso.","Está expresso.","Correta: a razoabilidade é implícita.","Está expressa."]],"w0a033":["Eficiência.","",["Estava no texto original.","Estava no texto original.","Estava no texto original.","Correta.","Estava no texto original."]],"1pwxt6l":["O sobrinho é parente de 3º grau: a nomeação viola a SV 13.","",["Não é permitida.","Correta.","O concurso não tem relação.","A SV 13 vale sem lei.","Diploma não afasta o nepotismo."]],"jcgg4e":["Art. 28: dolo ou erro grosseiro.","",["Não é qualquer culpa.","Correta.","Não é só dolo.","Culpa leve não basta.","Responde nessas hipóteses."]],"1ylhza":["À atividade administrativa (sentido material).","",["Órgãos são o sentido subjetivo.","Agentes são o sentido subjetivo.","Correta.","Entidades são o sentido subjetivo.","Os Poderes não são o critério."]],"y2imon":["Eficácia.","",["Não é de validade.","Não é de existência.","Correta.","Competência é elemento do ato.","Motivação integra a forma."]],"ytnorb":["Supremacia do interesse público.","",["A indisponibilidade gera sujeições, e não prerrogativas.","Correta.","A eficiência trata de resultados.","A publicidade trata da transparência.","A segurança jurídica trata da estabilidade."]],"1lqbk8f":["A Administração só pode fazer o que a lei autoriza.","",["Essa é a legalidade do particular.","Correta.","A lei não é dispensável.","Vale para a Administração.","Vale também para os atos discricionários."]],"14tuc2a":["Art. 20 da LINDB.","",["O art. 4º trata da omissão da lei.","Correta.","O art. 28 trata da responsabilidade do agente.","O art. 30 trata da segurança jurídica por regulamentos.","O art. 1º trata da vigência da lei."]]},"contratos":{"ysgvyj":["É o art. 156, §5º: a inidoneidade é a sanção mais grave e vale em TODAS as esferas (União, Estados, DF e Municípios), de 3 a 6 anos. É aplicada para infrações graves, como fraude na licitação.","Impedimento = só no ente que puniu, até 3 anos. Inidoneidade = todos os entes, 3 a 6 anos."],"1c4ibnp":["O limite geral do art. 125 é de 25% para obras, serviços e compras. Os 50% valem só para acréscimos em reforma de edifício ou de equipamento.",""],"1ffr0ws":["Fato do príncipe é ato geral do poder público (não dirigido ao contrato) que acaba encarecendo a execução, como o aumento de um tributo. Dá direito ao reequilíbrio econômico-financeiro (art. 124, II, d).",""],"5aslwh":["É o art. 125 da Lei 14.133: o contratado é obrigado a aceitar acréscimos ou supressões de até 25% do valor inicial atualizado.",""],"1a6e1ab":["Quem fica restrito ao ente que puniu é o IMPEDIMENTO de licitar e contratar (art. 156, §4º). A inidoneidade alcança todos os entes federativos (§5º).",""],"1fhrhsz":["O aumento de tributo é ato geral do Estado, que atinge todos e repercute indiretamente no contrato. Se fosse uma ação da própria Administração contratante sobre o contrato, seria fato da Administração.",""],"r0m95c":["Os serviços contínuos têm vigência de até 5 anos (art. 106), prorrogáveis até 10 anos (art. 107). Prazo indeterminado só existe quando a Administração é usuária de serviço público em regime de monopólio (art. 109).",""],"kosjtp":["É o art. 135: a repactuação reajusta o contrato com base na variação dos custos (como a convenção coletiva dos trabalhadores), e é usada nos serviços com dedicação exclusiva de mão de obra, como limpeza e vigilância.",""],"7obun3":["É o art. 104: cláusulas exorbitantes são prerrogativas que a Administração tem e que não existiriam num contrato privado comum, como alterar e extinguir unilateralmente, fiscalizar, punir e ocupar bens.",""],"fb68li":["É o art. 104, I: a alteração unilateral serve ao interesse público, mas deve respeitar os direitos do contratado, inclusive o equilíbrio econômico-financeiro.",""],"1ft8rqd":["É o art. 104, II. As hipóteses estão no art. 137, como o descumprimento de cláusulas e razões de interesse público.",""],"ereyw7":["É o art. 104, III e IV: fiscalizar e aplicar sanções motivadas pela inexecução total ou parcial.",""],"vu96ki":["É o art. 104, V: nos serviços essenciais, a ocupação provisória serve para apurar faltas contratuais e também quando o contrato é extinto, evitando a interrupção do serviço.",""],"1cxs6pm":["É o art. 104, §1º: o lucro e o equilíbrio do contrato são garantia do contratado. A Administração pode mudar o objeto, mas não mexer unilateralmente no preço.",""],"1bukagi":["É o art. 125: até 25% do valor inicial atualizado, nas obras, serviços e compras.",""],"1plwnrm":["É o art. 125. Atenção: os 50% são só para ACRÉSCIMOS em reforma. Para supressões, o limite continua 25%.",""],"gy7rh1":["Unilateralmente, a supressão só vai até 25% (art. 125). Uma redução maior só pode ser feita com a concordância do contratado.",""],"l7c7cl":["O reajuste aplica um índice de preços previsto no edital e no contrato, depois de 1 ano contado da data do orçamento estimado (art. 25, §7º, e art. 92, V).","Reajuste = índice. Repactuação = custos reais (mão de obra). Revisão = fato imprevisível."],"gvjr1h":["É o art. 135: a repactuação considera a variação dos custos demonstrada analiticamente, como os acordos e convenções coletivas.",""],"ymkf5t":["É o art. 124, II, d: força maior, caso fortuito, fato do príncipe ou fatos imprevisíveis (ou previsíveis de consequências incalculáveis) que tornem a execução mais onerosa. Pode ocorrer a qualquer tempo, sem esperar 1 ano.",""],"fqlxrt":["É a chamada álea extraordinária administrativa. Exemplo clássico: aumento de tributo que encarece os insumos do contratado.",""],"xr7wwk":["O fato da Administração atinge diretamente o contrato, como não liberar a área da obra ou não entregar o projeto. Pode justificar a suspensão ou a extinção do contrato pelo contratado.",""],"1ur60dq":["É o art. 106, desde que haja vantagem econômica e créditos orçamentários.",""],"i43j95":["É o art. 107: a prorrogação depende de previsão no edital, de a autoridade atestar que as condições continuam vantajosas e de o contratado concordar.",""],"17m1grj":["É o art. 110: até 10 anos sem investimento e até 35 anos quando o contratado faz investimentos que revertem ao patrimônio público.",""],"10aig5x":["É o art. 109. Exemplo: o contrato de fornecimento de energia ou água prestado por uma única concessionária.",""],"1gk7wkh":["É o art. 156: advertência, multa, impedimento de licitar e contratar e declaração de inidoneidade, da mais leve à mais grave.",""],"nusu3d":["É o art. 156, §3º: entre 0,5% e 30% do valor do contrato licitado ou celebrado.",""],"1rg90oy":["É o art. 156, §4º: vale só no ente federativo que aplicou a sanção (da Administração direta e indireta dele), pelo prazo máximo de 3 anos.",""],"9o66fq":["É o art. 156, §5º: alcança todos os entes federativos, pelo prazo mínimo de 3 e máximo de 6 anos.",""],"n07qxh":["O prazo é de 3 a 6 anos (art. 156, §5º). Dois anos não aparece entre os prazos das sanções da Lei 14.133.",""],"1wamru0":["É o art. 156, §7º: a multa pode somar-se à advertência, ao impedimento ou à inidoneidade. As outras sanções não se cumulam entre si.",""],"197vojc":["É o art. 96, §1º: caução em dinheiro ou títulos da dívida pública, seguro-garantia, fiança bancária ou título de capitalização. Quem escolhe a modalidade é o contratado; a Administração decide apenas se exige garantia.",""],"b946ym":["É o art. 98: até 5% em regra, e até 10% quando houver alta complexidade técnica e riscos envolvidos, com justificativa.",""],"6j7j70":["É o art. 99: nesse caso a seguradora assume o compromisso de concluir a obra se o contratado falhar (cláusula de retomada).",""],"17vzz9y":["É o art. 137, §2º, IV, e §3º, II: atraso de mais de 2 meses permite ao contratado pedir a extinção ou suspender a execução até a regularização. Antes desse prazo ele deve continuar executando.",""],"1m7j38f":["É o art. 117: um ou mais fiscais, que podem contar com terceiros contratados para ajudá-los.",""],"1lklph1":["No contrato, as partes têm interesses opostos (uma quer o serviço, a outra o pagamento). No convênio, os partícipes têm objetivo comum e cooperam entre si, como União e Município num programa de saúde.",""],"12rr8mz":["É o art. 184, enquanto não houver regulamento específico.",""],"c8cil":["Art. 125: 25%.","",["10% não é o limite.","20% não é o limite.","Correta.","30% não é o limite.","50% é só para reforma de edifício ou equipamento."]],"1fx56dp":["Art. 125: 50%.","",["25% é o limite geral.","30% não é o limite.","40% não é o limite.","Correta.","100% não existe na lei."]],"1clgoz5":["Fato do príncipe: ato geral do Estado com reflexo indireto no contrato.","",["Fato da Administração atinge o contrato diretamente.","Correta.","Caso fortuito é evento da natureza ou humano imprevisível, não ato estatal.","Interferência imprevista é condição material preexistente, descoberta na execução (como solo rochoso).","Força maior é evento irresistível, não ato do poder público."]],"1ksuriw":["Art. 106: 5 anos.","",["1 ano não é o limite.","2 anos não é o limite.","Correta.","10 anos é o limite com prorrogações (art. 107).","35 anos é para contrato de receita com investimento."]],"5iavet":["Art. 156, §5º: de 3 a 6 anos.","",["Não é até 1 ano.","Não é até 2 anos.","Correta.","Não é até 10 anos.","Tem prazo definido."]],"39lbsi":["Art. 156, §4º: o ente federativo que aplicou a sanção.","",["Todos os entes é a inidoneidade.","Correta.","Não é só a União.","Não é só o Município.","Não é só a estatal."]],"t4vovj":["Art. 156, §3º: 30% do valor do contrato.","",["10% não é o máximo.","20% não é o máximo.","Correta.","50% passa do limite.","100% passa do limite."]],"qkh4wu":["Art. 135: repactuação.","",["Revisão é para fatos imprevisíveis.","Correta.","Atualização monetária corrige atraso de pagamento.","Reajuste por índice é para os demais contratos.","Compensação não é mecanismo da lei."]],"1u43g1j":["Art. 96, §1º: o contratado.","",["A Administração decide se exige, mas não escolhe a modalidade.","Correta.","O TCU não participa.","O banco só presta a fiança.","O fiscal acompanha a execução."]],"184q4f4":["Art. 137, §§2º e 3º: 2 meses.","",["15 dias é pouco.","30 dias é pouco.","Correta.","6 meses não é o prazo.","1 ano não é o prazo."]],"y12tvg":["As cláusulas econômico-financeiras não podem ser alteradas sem concordância do contratado (art. 104, §1º).","",["É cláusula exorbitante (inciso I).","É cláusula exorbitante (inciso II).","É cláusula exorbitante (inciso III).","É cláusula exorbitante (inciso V).","Correta."]]},"controle":{"1s8xj5i":["No Brasil, só o Judiciário decide com força de coisa julgada definitiva (CF, art. 5º, XXXV: a lei não exclui da apreciação do Judiciário lesão ou ameaça a direito). A decisão administrativa sempre pode ser levada ao Judiciário.","Não confundir com o sistema francês (contencioso administrativo), que o Brasil não adota."],"jvf3p2":["Nas contas do Presidente, o TCU só emite PARECER PRÉVIO em 60 dias (art. 71, I). Quem JULGA é o Congresso Nacional (art. 49, IX). O TCU julga as contas dos demais administradores (art. 71, II).",""],"sgna3h":["É o art. 71, §3º, da CF: a decisão vale como título executivo extrajudicial e pode ser executada diretamente, sem novo processo de conhecimento. A execução é proposta pelo ente público lesado, não pelo Tribunal de Contas.",""],"de8ayz":["É o art. 71, §§1º e 2º: no CONTRATO, quem susta é o Congresso, que pede ao Executivo as medidas cabíveis; se em 90 dias nada for feito, o TCU decide. No ATO administrativo, o próprio TCU pode sustar (art. 71, X).",""],"ne78pc":["A interceptação telefônica é cláusula de reserva de jurisdição (CF, art. 5º, XII): só o juiz pode decretá-la. A CPI pode quebrar o sigilo dos REGISTROS telefônicos (quem ligou para quem), mas não escutar as conversas.",""],"12ht230":["É o art. 31, §2º, da CF: a Câmara só derruba o parecer prévio com 2/3 dos seus membros.",""],"11zknq0":["O art. 31, §4º, VEDA a criação de novos Tribunais, Conselhos ou órgãos de Contas Municipais. Os que já existiam em 1988 (como os de São Paulo e do Rio de Janeiro) foram mantidos.",""],"13hxlg8":["É o art. 71, §3º, da CF: eficácia de título executivo.",""],"6cne9c":["É a classificação pelo órgão que controla: a própria Administração (autotutela), o Legislativo (com auxílio do Tribunal de Contas) ou o Judiciário (provocado por ação).",""],"z1ej0c":["Interno: dentro do mesmo Poder (exemplo: a CGU sobre os ministérios). Externo: um Poder sobre outro (exemplo: o Congresso com o TCU sobre o Executivo, ou o Judiciário anulando ato do Executivo).",""],"9gkbhe":["É a classificação pelo momento: prévio (antes do ato, como a autorização do Senado para empréstimo externo), concomitante (durante, como a fiscalização de uma obra) e posterior (depois, como o julgamento de contas).",""],"96fdlq":["É a Súmula 473 do STF: a Administração anula os atos ilegais e revoga os inconvenientes ou inoportunos, respeitados os direitos adquiridos e ressalvada a apreciação judicial.",""],"d19oqr":["Entre o ministério e a autarquia não há hierarquia, só vinculação. O controle (tutela ou supervisão ministerial) verifica se a entidade cumpre as finalidades da lei que a criou e só existe nos limites da lei.",""],"1vvhdxv":["Como não há hierarquia entre o ministério e a entidade da indireta, o recurso de uma decisão da autarquia ao ministro é \"impróprio\" e só cabe se a lei expressamente o prever.",""],"x9djqt":["É o art. 71 da CF. O TCU auxilia o Congresso, mas tem competências próprias e não é subordinado a ele.",""],"1lzbbbr":["É o art. 71, I: o parecer prévio deve ser elaborado em 60 dias a contar do recebimento das contas. O julgamento cabe ao Congresso.",""],"1nokscy":["É o art. 49, IX, da CF: competência exclusiva do Congresso.",""],"1a68xhk":["É o art. 71, II: aqui o TCU JULGA (e não só opina), inclusive as contas de quem causar perda ou extravio de dinheiro público.",""],"doz2fz":["É o art. 71, III: ficam de fora as nomeações para cargo em comissão e as melhorias posteriores que não alterem o fundamento legal da aposentadoria.",""],"1829ua0":["É o art. 71, §3º: título executivo.",""],"g3z29z":["É o art. 71, §1º: o Congresso susta o contrato e solicita ao Executivo as medidas cabíveis.",""],"ctmow3":["É o art. 71, §2º: se o Congresso ou o Executivo não agirem em 90 dias, o TCU decide.",""],"1l8fzfz":["É o art. 71, X: o TCU primeiro dá prazo para o órgão corrigir a ilegalidade (inciso IX); se não for atendido, susta o ATO e comunica à Câmara e ao Senado.","Ato = o TCU susta. Contrato = o Congresso susta."],"9ehsfa":["É a Súmula Vinculante 3: há contraditório e ampla defesa quando a decisão puder anular ou revogar ato que beneficie o interessado, EXCETO na apreciação da legalidade do ato inicial de aposentadoria, reforma e pensão, que é ato complexo ainda em formação.",""],"f8hza4":["É o Tema 445 do STF: em respeito à segurança jurídica, o Tribunal de Contas tem 5 anos, contados da chegada do processo a ele, para julgar a legalidade da concessão inicial. Passado esse prazo, o ato é considerado registrado.",""],"1sv1ggu":["É o art. 31 da CF: Câmara Municipal com auxílio do Tribunal de Contas do Estado (ou do Município, onde já existia). Em Minas Gerais, é o TCE-MG.",""],"1qie4vs":["É o art. 31, §2º: só por 2/3 dos membros da Câmara.",""],"y6xwta":["É o art. 31, §4º. Os já existentes em 1988 continuam.",""],"o4e8mz":["No RE 848.826 (Tema 835), o STF decidiu que, para a inelegibilidade da Lei da Ficha Limpa, quem julga TODAS as contas do Prefeito (de governo e de gestão) é a Câmara. O parecer do Tribunal de Contas só deixa de prevalecer por 2/3.",""],"1mcdrro":["É o art. 58, §3º, da CF: requerimento de 1/3 dos membros da Casa, fato determinado e prazo certo. As conclusões vão ao Ministério Público, porque a CPI não pune ninguém.",""],"8h5ysd":["É reserva de jurisdição: só o juiz pode. Também não podem decretar busca domiciliar nem prisão (salvo flagrante).",""],"10bqn9e":["É a jurisprudência do STF: a quebra de sigilo bancário, fiscal e de registros telefônicos é permitida, desde que por decisão fundamentada e aprovada pela maioria da comissão.",""],"1a1cc7b":["É o art. 49, V: o Congresso susta, por decreto legislativo, o regulamento que vai além da lei ou a lei delegada que excede os limites da delegação.",""],"lmwztg":["O Judiciário verifica a legalidade (inclusive moralidade, razoabilidade e proporcionalidade), mas não substitui o administrador na escolha de conveniência e oportunidade (mérito).",""],"1ieuhsj":["Ato desproporcional é ilegítimo. Nesse caso o juiz não revoga (não avalia conveniência): ele ANULA, porque a falta de razoabilidade é vício de legalidade.",""],"146skg1":["É o art. 5º, LXXIII, da CF: o autor fica isento de custas e sucumbência, salvo comprovada má-fé. Cidadão é quem está em dia com a Justiça Eleitoral (eleitor).",""],"c62sb9":["O Tribunal de Contas tem autonomia e competências próprias previstas na CF (art. 71). \"Auxiliar\" significa ajudar no controle, não estar abaixo hierarquicamente.",""],"1p9uhga":["É o art. 73 da CF: 9 Ministros, com sede no DF. Um terço é escolhido pelo Presidente (com aprovação do Senado) e dois terços pelo Congresso.",""],"14j0qn":["Revogar é exclusivo da Administração que praticou o ato. O Judiciário só ANULA atos ilegais.",""],"6bvrzf":["Art. 49, IX: Congresso Nacional.","",["O TCU só emite parecer prévio.","O STF não julga contas.","Correta.","O Senado sozinho não julga.","A CGU é controle interno."]],"17rx0uz":["Art. 71, I: emite parecer prévio.","",["Quem julga é o Congresso.","Correta.","Não arquiva.","Não existe essa competência.","Não aprova sozinho."]],"120j8g7":["Art. 71, §1º: Congresso Nacional.","",["O TCU só decide se o Congresso não agir em 90 dias.","Correta.","O STF não participa.","O Presidente é quem adota medidas a pedido do Congresso.","O MP não susta contratos."]],"1031z8p":["Art. 71, §2º: 90 dias.","",["30 dias não é o prazo.","60 dias é o prazo do parecer prévio.","Correta.","120 dias não é o prazo.","180 dias não é o prazo."]],"3fdwfn":["Art. 31, §2º: dois terços da Câmara.","",["Maioria simples não basta.","Maioria absoluta não basta.","Correta.","Três quintos é o quórum de emenda constitucional.","Unanimidade não é exigida."]],"1abu75c":["Art. 31: Tribunal de Contas do Estado de Minas Gerais.","",["O TCU fiscaliza recursos federais, não as contas do Município.","Correta.","Belo Vale não tem, e é vedado criar.","A CGU é controle interno federal.","O TJMG é Judiciário."]],"sfq53q":["Apreciação inicial de aposentadoria, reforma e pensão.","",["Em regra há contraditório.","Correta.","A multa exige contraditório.","A tomada de contas exige contraditório.","Não é essa a exceção."]],"ihdfxy":["Art. 71, §3º: título executivo.","",["Não é sentença judicial.","Correta.","Não é lei.","Não é parecer.","Não é recomendação."]],"e77fs4":["A busca domiciliar é reserva de jurisdição.","",["Pode ouvir testemunhas.","Pode, fundamentadamente.","Correta.","Pode requisitar documentos.","Pode convocar investigados."]],"17kpp7z":["Finalístico (tutela, supervisão ministerial).","",["Não há hierarquia entre pessoas jurídicas diferentes.","Correta.","Não é judicial.","O ministério não é o TCU.","O controle existe."]],"1e6pjdi":["A legalidade, incluindo razoabilidade e proporcionalidade.","",["O mérito não é examinado.","Correta.","Conveniência é mérito.","Oportunidade é mérito.","O Judiciário controla a legalidade."]]},"improbidade":{"j5ge4a":["A Lei 14.230/2021 acabou com a improbidade culposa: hoje todas as espécies (arts. 9º, 10 e 11) exigem dolo (Lei 8.429, art. 1º, §1º). Erro, negligência ou imprudência podem gerar outra responsabilidade, mas não improbidade.",""],"vcg9d6":["Depois da Lei 14.230, a violação de princípios (art. 11) tem como sanções só a multa civil de até 24 vezes a remuneração e a proibição de contratar por até 4 anos (art. 12, III). Não há perda da função nem suspensão dos direitos políticos.",""],"1fokqc1":["É o art. 2º da Lei Anticorrupção: a empresa responde independentemente de culpa ou dolo dos dirigentes, bastando o ato lesivo praticado em seu interesse ou benefício.","Lei 8.429 (improbidade) = exige dolo. Lei 12.846 (anticorrupção, pessoa jurídica) = responsabilidade objetiva."],"1l3e6ux":["É o art. 1º, §1º, da Lei 8.429: só são atos de improbidade as condutas dolosas. A antiga modalidade culposa do art. 10 foi extinta.",""],"ntwudv":["No art. 11 não há suspensão dos direitos políticos (art. 12, III). Suspensão existe no art. 9º (até 14 anos) e no art. 10 (até 12 anos).",""],"1qdqcw5":["É o art. 23 da Lei 8.429 (com a Lei 14.230): 8 anos a partir do fato ou, nas infrações permanentes, do dia em que cessou a permanência. O ressarcimento ao erário por ato doloso de improbidade continua imprescritível (STF, Tema 897).",""],"1c45cng":["É o art. 16, §3º, da Lei 12.846: a leniência reduz a multa e afasta algumas sanções, mas nunca dispensa a reparação integral do dano.",""],"msxz4z":["No Tema 1.199 (ARE 843.989), o STF decidiu que os novos prazos de prescrição (geral e intercorrente) só valem a partir da publicação da Lei 14.230/2021 (26/10/2021).",""],"1cqd4tk":["É o art. 1º, §1º, da Lei 8.429.",""],"1ibfml4":["É o art. 1º, §2º: não basta a voluntariedade do agente. É preciso querer o resultado ilícito descrito nos arts. 9º, 10 ou 11 (dolo específico).",""],"1lony2q":["É o art. 1º, §§3º e 8º: interpretar a lei de forma diferente, com base em jurisprudência, mesmo que depois não prevaleça, não é improbidade.",""],"rwp06q":["O art. 9º pune quem obtém vantagem patrimonial indevida em razão do cargo, como receber propina. É a espécie mais grave.","Art. 9º = enriquecimento ilícito. Art. 10 = lesão ao erário. Art. 11 = violação de princípios."],"1vrtvbh":["Depois da Lei 14.230, o art. 10 exige perda patrimonial efetiva e comprovada. Não existe mais dano presumido (in re ipsa).",""],"159kxmx":["A Lei 14.230 trocou \"notadamente\" por uma lista fechada: só são improbidade do art. 11 as condutas descritas nos seus incisos.",""],"1jrynxp":["O rol passou a ser TAXATIVO. Antes da reforma era exemplificativo.",""],"zpw0ko":["É o art. 9º, X: o agente se enriquece ilicitamente ao receber vantagem para deixar de fazer o que devia.",""],"vy413i":["É o art. 10, VIII: frustrar a licitação ou dispensá-la indevidamente, com perda patrimonial efetiva, é lesão ao erário.",""],"1py67c2":["É o art. 11, XI: nomear cônjuge, companheiro ou parente até o 3º grau para cargo em comissão ou função de confiança, inclusive por ajuste mútuo (nepotismo cruzado). Reflete a SV 13.",""],"7r2rpo":["É o art. 12, I: perda dos bens acrescidos, perda da função, suspensão dos direitos políticos até 14 anos, multa igual ao acréscimo patrimonial e proibição de contratar até 14 anos.",""],"vtkfz8":["É o art. 12, II: ressarcimento, perda da função, suspensão dos direitos políticos até 12 anos, multa igual ao dano e proibição de contratar até 12 anos.","Art. 9º = 14 anos. Art. 10 = 12 anos. Art. 11 = sem suspensão (proibição de contratar até 4 anos)."],"1vge4ns":["É o art. 12, III: só multa civil (até 24 vezes a remuneração) e proibição de contratar ou receber benefícios por até 4 anos.",""],"4v9d94":["É o art. 12, III: até 24 vezes o valor da remuneração recebida pelo agente.",""],"7mqae1":["É o art. 12, III.",""],"hlhdic":["É o art. 20 da Lei 8.429: as duas sanções só valem depois do trânsito em julgado. Antes disso, o juiz pode apenas afastar o agente do cargo, por até 90 dias (prorrogáveis), se necessário à instrução.",""],"aqpcie":["É o art. 23, caput.",""],"3mkrs8":["É o art. 23, §§4º e 5º: depois de cada marco interruptivo (como o ajuizamento ou a sentença), o prazo volta a correr pela metade, ou seja, 4 anos.",""],"16kofj6":["No Tema 1.199, o STF decidiu que a extinção da improbidade culposa alcança os atos anteriores à lei, desde que não haja condenação transitada em julgado. O juiz deve verificar se houve dolo.",""],"y19dju":["Tema 1.199: os novos prazos valem a partir de 26/10/2021.",""],"1mwid2c":["Nas ADIs 7.042 e 7.043, o STF derrubou a exclusividade do Ministério Público criada pela Lei 14.230. A pessoa jurídica lesada (por exemplo, o Município) também pode propor a ação.",""],"ul7h63":["É o art. 16, §3º: depois da reforma, não basta a urgência presumida. É preciso demonstrar perigo de dano irreparável ou risco ao resultado útil do processo.",""],"12w3r4n":["É o art. 17-B: o acordo exige ressarcimento integral do dano e reversão da vantagem indevida à pessoa jurídica lesada.",""],"dvr31v":["São os arts. 1º e 2º: a responsabilidade da empresa é objetiva, nas esferas administrativa e civil (não penal).",""],"15dj59a":["É o art. 3º da Lei 12.846: os dirigentes e administradores respondem na medida da sua culpabilidade (responsabilidade subjetiva).",""],"5pkr4i":["É o art. 6º, I: de 0,1% a 20% do faturamento bruto do último exercício antes do processo, nunca menor que a vantagem obtida. Se não for possível usar o faturamento, a multa vai de R$ 6 mil a R$ 60 milhões (§4º).",""],"16ktuct":["É o art. 6º, II: a empresa publica a decisão às suas custas em meios de comunicação, no próprio estabelecimento e no seu site.",""],"mlmype":["É o art. 19: perdimento de bens, suspensão ou interdição parcial das atividades, dissolução compulsória e proibição de receber incentivos e empréstimos públicos de 1 a 5 anos.",""],"9wgb3r":["É o art. 16, §2º: também isenta da publicação extraordinária e da proibição de receber incentivos.",""],"1h6srsw":["É o art. 16, §3º.",""],"vi513p":["É o art. 25: 5 anos contados da ciência da infração ou, se permanente ou continuada, do dia em que cessou.",""],"12gbgp":["A responsabilidade da pessoa jurídica é OBJETIVA (art. 2º). Quem responde subjetivamente são os dirigentes (art. 3º).",""],"18tn5o8":["Art. 1º, §1º: dolo.","",["A culpa grave não basta mais.","Correta.","A culpa não configura improbidade.","Dano sem dolo não basta.","Nexo sem dolo não basta."]],"rycil7":["Art. 12, I: 14 anos.","",["4 anos é a proibição de contratar do art. 11.","8 anos é a prescrição.","12 anos é o art. 10.","Correta.","20 anos não existe."]],"7oxblo":["Art. 12, III: não há suspensão dos direitos políticos.","",["Há multa civil.","Há proibição de contratar.","Correta.","O ressarcimento é devido se houver dano.","Há sanções."]],"1k6p8i4":["Art. 23: 8 anos.","",["4 anos é a intercorrente.","5 anos era o prazo antigo e é o da Lei Anticorrupção.","Correta.","10 anos não é o prazo.","20 anos não é o prazo."]],"1mdpsco":["Art. 12, III: 24 vezes a remuneração.","",["10 vezes não é o limite.","Correta.","O valor do dano é a multa do art. 10.","O valor do acréscimo é a multa do art. 9º.","Não é em salários mínimos."]],"1nyzz41":["Perda patrimonial efetiva e comprovada.","",["Enriquecimento é o art. 9º.","Correta.","Violação de princípio é o art. 11.","Culpa não basta.","Exige dolo e dano."]],"hc6ay":["Art. 6º, I: 0,1% a 20% do faturamento bruto.","",["Não é 1% a 10%.","Correta.","Não é 5% a 50%.","R$ 6 mil a R$ 60 milhões só quando não dá para usar o faturamento.","Não é 10% a 30%."]],"xctlqs":["Art. 16, §2º: 2/3.","",["1/3 é pouco.","1/2 não é o limite.","Correta.","3/4 passa do limite.","Não isenta totalmente."]],"k0c0g5":["Objetiva (art. 2º).","",["Subjetiva é a dos dirigentes.","Correta.","A lei não trata de responsabilidade penal.","Existe.","A empresa responde."]],"1fv6tcy":["Art. 20: com o trânsito em julgado.","",["A citação não basta.","A sentença de 1º grau não basta.","Correta.","O recebimento da inicial não basta.","A liminar só pode afastar provisoriamente."]],"16n76va":["É irretroativo.","",["Não retroage.","Correta.","Vale para todos os agentes.","Foi mantido.","Vale para todas as espécies."]]},"licitacoes":{"hbyjr":["As modalidades atuais são cinco (art. 28): pregão, concorrência, concurso, leilão e diálogo competitivo. Tomada de preços e convite, da antiga Lei 8.666, não existem mais.","Macete \"PC CLD\": Pregão, Concorrência, Concurso, Leilão, Diálogo competitivo."],"q68ifz":["A inexigibilidade acontece sempre que a competição é inviável, e o art. 74 lista casos \"em especial\", ou seja, o rol é EXEMPLIFICATIVO. Taxativo é o rol de dispensa (art. 75), em que a competição seria possível, mas a lei permite não licitar.",""],"5c22kz":["É o art. 6º, XLI, e o art. 29: bens e serviços comuns (com padrões de desempenho definidos objetivamente no edital, como material de escritório) são licitados obrigatoriamente por pregão.",""],"1n93n67":["É o art. 28. O diálogo competitivo é a única modalidade nova.",""],"31e0sl":["A regra do art. 17 é: primeiro o julgamento das propostas, depois a habilitação só do vencedor. A inversão (habilitação antes) é exceção, com motivação e previsão no edital.",""],"1cfuh40":["É o art. 74, que usa a expressão \"em especial\". Qualquer situação de competição inviável gera inexigibilidade.",""],"1cp9b4k":["O art. 75, VIII, limita o contrato emergencial a 1 ano e proíbe a prorrogação e a recontratação da mesma empresa com base na mesma emergência.",""],"mkycqx":["É o art. 6º, XL: vence quem oferecer o maior lance. Pode ser conduzido por servidor ou por leiloeiro oficial.",""],"82xnj2":["É o art. 1º: União, Estados, DF e Municípios, com seus fundos especiais e as entidades controladas.",""],"13wrukv":["É o art. 1º, §1º, da Lei 14.133: as estatais têm lei própria (Lei das Estatais), salvo algumas regras penais da nova lei, que se aplicam a elas também.",""],"1n5o6e9":["É o art. 28.",""],"8b3mtb":["É o art. 28, §2º: nem a lei local nem o edital podem inventar modalidade ou misturar as existentes.",""],"17ls9oa":["É o art. 6º, XLI, e o art. 29.",""],"vs5wh2":["É o art. 6º, XLI. Pregão nunca usa técnica e preço nem melhor técnica.",""],"1bozpro":["O art. 29, parágrafo único, afasta o pregão de obras e de serviços técnicos especializados intelectuais. Ele só cabe para serviço COMUM de engenharia (como manutenção predial simples). Obra vai para concorrência.",""],"1y32l7c":["É o art. 6º, XXXIX: o critério é melhor técnica ou conteúdo artístico, com prêmio ou remuneração ao vencedor. Exemplo: escolha de projeto arquitetônico.","Não confundir o concurso (modalidade de licitação) com o concurso público para cargos."],"6ui0r7":["É o art. 6º, XL: critério de maior lance.",""],"ffp6my":["É o art. 6º, XLII, e art. 32: a Administração dialoga com licitantes previamente selecionados para desenvolver a solução, e depois eles apresentam a proposta final.",""],"qohz3t":["É o art. 33: menor preço, maior desconto, melhor técnica ou conteúdo artístico, técnica e preço, maior lance (leilão) e maior retorno econômico (contrato de eficiência).",""],"13oasw5":["É o art. 17: a sequência é preparatória, edital, propostas e lances, julgamento, habilitação, recursos e homologação.",""],"yuhowi":["É o art. 17, §1º: exige ato motivado com explicação dos benefícios e previsão expressa no edital.",""],"x1ri8q":["É o art. 17, §2º: a forma presencial é exceção e precisa de motivação.",""],"1bapc8p":["É o art. 17, §2º: ata e gravação em áudio e vídeo, juntadas aos autos.",""],"1w06zsb":["É o art. 174: o PNCP é o site oficial de divulgação dos atos da lei. A publicação no PNCP é condição de eficácia do contrato (art. 94).",""],"1f9d6sp":["É o art. 8º: o agente de contratação conduz a licitação. Deve ser servidor efetivo ou empregado público do quadro permanente.",""],"1fp4jv6":["É o art. 8º, §5º.",""],"1hww6zs":["É o art. 18: a fase de planejamento inclui estudo técnico preliminar, termo de referência ou projeto básico ou executivo, orçamento estimado, análise de riscos e minuta do edital.",""],"1fkwg1k":["É o art. 74: quando só existe um fornecedor ou quando não há como comparar objetivamente (como um artista consagrado).",""],"1foczcu":["É o art. 74, II: contratação direta ou por empresário exclusivo, consagrado pela crítica ou pela opinião pública.",""],"ahq3km":["É o art. 74, III: exige notória especialização. É vedada para serviços de publicidade e divulgação.",""],"1arma5p":["É o art. 74 (\"em especial\").",""],"12jpij4":["É o art. 75: só a lei pode criar casos de dispensa, porque a competição seria possível. O gestor não pode criar novas hipóteses.","Dispensa = rol taxativo (competição possível). Inexigibilidade = rol exemplificativo (competição inviável)."],"f5904j":["É o art. 75, VIII: 1 ano contado da emergência, vedadas a prorrogação e a recontratação da mesma empresa.",""],"tqvrru":["É o art. 182: o Executivo federal atualiza os valores todo ano pelo IPCA-E, em decreto que vale para todos os entes.",""],"c7uuju":["É o art. 76: na licitação dispensada, a própria lei já afasta a licitação (exemplo: doação de bem para outro órgão público). Na dispensável (art. 75), o gestor PODE dispensar.",""],"rtptna":["É o art. 78: credenciamento, pré-qualificação, procedimento de manifestação de interesse, sistema de registro de preços e registro cadastral.",""],"uqrskj":["É o art. 4º da Lei 14.133, que manda aplicar os arts. 42 a 49 da LC 123/2006 (empate ficto e tratamento diferenciado).",""],"80sz4q":["A tomada de preços foi extinta. Hoje não existe modalidade definida pelo valor da contratação.",""],"oynm9j":["É o art. 193: a Lei 8.666, a Lei do Pregão (10.520) e o RDC (12.462) foram revogados ao fim do período de transição, em 30/12/2023.",""],"1iudo9t":["O convite foi extinto.","",["É modalidade.","É modalidade.","Correta.","É modalidade.","É modalidade nova."]],"mrk358":["Art. 6º, XL: maior lance.","",["Menor preço é do pregão e da concorrência.","Maior desconto é do pregão e da concorrência.","Correta.","Técnica e preço é da concorrência.","Melhor técnica é do concurso e da concorrência."]],"104qwz2":["Pregão, obrigatório para bens comuns.","",["Concurso escolhe trabalho técnico ou artístico.","Leilão é para vender bens.","Correta.","Diálogo competitivo é para inovação.","Convite foi extinto."]],"zihifb":["Art. 74, II: inexigibilidade.","",["Dispensa pressupõe competição possível.","Correta.","Licitação dispensada é para alienação de bens.","Não há licitação.","Não há licitação."]],"1l7vksc":["Art. 75, VIII: 1 ano.","",["6 meses não é o prazo.","Correta.","2 anos passa do limite.","5 anos é o dos serviços contínuos.","Não pode ser indeterminado."]],"qfxki9":["Art. 17: julgamento antes da habilitação.","",["Essa é a exceção (inversão de fases).","Correta.","Há habilitação.","Há julgamento.","A homologação é o último ato."]],"1gvwhh4":["Art. 6º, XXXIX: concurso.","",["Concorrência não dá prêmio.","Correta.","Leilão é para vender bens.","Pregão é para bens comuns.","Diálogo é para inovação."]],"7c4c2a":["Art. 174: PNCP.","",["O SIAFI é sistema financeiro.","Correta.","O SICAF é cadastro de fornecedores.","O ComprasNet é plataforma de compras federal.","O Diário Oficial não é o portal da lei."]],"8a21e2":["Art. 17, §2º: eletrônica.","",["A presencial é exceção motivada.","Correta.","Não existe.","Não existe.","Não existe."]],"19wier3":["Art. 75: taxativo.","",["Exemplificativo é o de inexigibilidade.","Correta.","Existe.","O gestor não cria hipóteses.","O TCU não cria hipóteses."]],"13ac820":["Lei 13.303/2016.","",["Foi revogada e não era específica.","Exclui as estatais.","Correta.","Era a Lei do Pregão, revogada.","Era o RDC, revogado."]]},"organizacao":{"gam4ds":["Desconcentrar é dividir competências DENTRO da mesma pessoa jurídica, criando órgãos (secretarias, departamentos). Como tudo fica na mesma pessoa, há hierarquia entre os órgãos.","DesconCentração = dentro (órgãos, hierarquia). Descentralização = para outra pessoa (sem hierarquia)."],"14oou4n":["A sociedade de economia mista é SEMPRE sociedade anônima (Lei 13.303/2016, art. 4º), com maioria das ações com direito a voto do ente público. Quem pode adotar qualquer forma societária é a empresa pública.",""],"1balw46":["É o art. 37, XIX, da CF: a lei CRIA diretamente a autarquia, sem necessidade de registro. Ela exerce atividade típica de Estado e tem as mesmas prerrogativas da Administração direta. Exemplos: INSS, Banco Central.",""],"1dzw4q5":["Na outorga (descentralização por serviços), a lei cria uma entidade da Administração indireta e passa a ela a titularidade e a execução. Na delegação (por colaboração), passa-se só a execução, por contrato ou ato (concessão, permissão).",""],"10nidf8":["Entre pessoas jurídicas diferentes não há hierarquia. O ente central exerce só controle finalístico (tutela ou supervisão ministerial), nos limites da lei.",""],"1cy29gz":["É a Lei 9.649/1998 (arts. 51 e 52): a agência executiva não é uma nova entidade, mas um título dado por decreto a uma autarquia ou fundação que tem plano de reestruturação e celebra contrato de gestão com o ministério.",""],"1efeyfn":["A OSCIP firma TERMO DE PARCERIA (Lei 9.790/1999). O contrato de gestão é o instrumento da Organização Social (OS, Lei 9.637/1998).","OS = Contrato de gestão. OSCIP = termo de Parceria."],"91641n":["É a Súmula 525 do STJ: a Câmara tem só personalidade judiciária, e pode ir a juízo apenas para defender seus direitos institucionais (como prerrogativas e funcionamento), não para cobrar dinheiro do Município.",""],"i8gp6h":["Na centralização, a própria União, Estado, DF ou Município executa a atividade pelos seus órgãos (Administração direta).",""],"1aabsf6":["Na descentralização há duas pessoas diferentes: o ente político e a entidade da indireta (outorga) ou o particular (delegação).",""],"1oi7a52":["Ocorre dentro da mesma pessoa jurídica e gera hierarquia entre os órgãos. Pode existir também dentro de uma autarquia, por exemplo nas superintendências regionais do INSS.",""],"1sznchm":["Na desconcentração surge um ÓRGÃO, que não tem personalidade jurídica. Nova pessoa jurídica só aparece na descentralização por outorga.",""],"1cxdxbu":["É feita por lei, para entidade da Administração indireta.",""],"ugcspt":["Por contrato (concessão, permissão) ou ato unilateral (autorização). A titularidade continua com o Estado.",""],"157h2q2":["É a teoria do órgão (Otto Gierke): o agente age em nome do órgão, e o órgão integra a pessoa jurídica, que é quem responde. A Lei 9.784 (art. 1º, §2º, I) define órgão como unidade de atuação sem personalidade.",""],"1x4fe47":["É a classificação de Hely Lopes Meirelles: Casas Legislativas, Presidência, tribunais, MP e Tribunais de Contas. Não se subordinam a nenhum outro órgão.",""],"125968b":["Têm autonomia administrativa, financeira e técnica e participam das decisões de governo. Exemplos: ministérios e secretarias.","Hely: independentes > autônomos > superiores > subalternos."],"1mlwt6g":["É o art. 4º, II, do DL 200/1967. A doutrina inclui também os consórcios públicos de direito público (associações públicas).",""],"1f3657u":["É o art. 37, XIX, da CF.",""],"ak1k1e":["Por isso tem prerrogativas de Fazenda Pública: bens públicos, prazos processuais em dobro e pagamento de dívidas judiciais por precatório.",""],"y2x810":["É o art. 37, XIX: para empresa pública, sociedade de economia mista e fundação, a lei só AUTORIZA. A entidade passa a existir com o registro dos atos constitutivos.","Autarquia = a lei cria. Estatais e fundações = a lei autoriza."],"1eileg7":["É o art. 4º da Lei 13.303/2016.",""],"vednoy":["É o art. 3º da Lei 13.303/2016: inclusive a forma unipessoal (só um sócio, como a Caixa).",""],"1ekdu7i":["É o art. 3º da Lei 13.303: não há sócio privado. Outros entes públicos e entidades da Administração indireta podem participar, desde que o controle seja de um ente político.",""],"1dkjbxy":["É o art. 4º da Lei 13.303: o capital é misto (público e privado), mas o controle é do Estado. Exemplos: Petrobras, Banco do Brasil.",""],"1svxpyb":["É o art. 109, I, da CF, que menciona expressamente as empresas públicas federais (como a Caixa e os Correios).",""],"1ao8mek":["A sociedade de economia mista não está no art. 109, I. Suas causas vão para a Justiça Estadual (Súmula 556 do STF), salvo se a União intervier no processo.",""],"7luc7r":["É o art. 37, XIX, parte final, da CF.",""],"1wmxkz1":["O \"regime especial\" significa mais autonomia: dirigentes com mandato fixo, que não podem ser exonerados livremente, e autonomia técnica e financeira. Exemplos: ANATEL, ANEEL, ANVISA.",""],"1b22atd":["É a regra da Lei 9.986/2000, art. 6º, alterada pela Lei 13.848/2019: mandato de 5 anos, sem recondução, com mandatos não coincidentes.",""],"qhfyi0":["É a Lei 9.649/1998: a qualificação depende de plano estratégico e de contrato de gestão com o ministério supervisor.",""],"w95wql":["É o art. 6º, I e §1º, da Lei 11.107/2005: a associação pública integra a Administração indireta de todos os entes consorciados. O consórcio de direito privado segue as normas de direito público em licitação, contratos e admissão de pessoal.",""],"zc1nad":["É a Lei 11.107/2005 (arts. 3º e 5º): os entes assinam o protocolo de intenções, cada um o ratifica por lei e só então o contrato de consórcio se forma.",""],"g124y0":["É a Lei 9.637/1998: a OS é entidade privada sem fins lucrativos, qualificada pelo Executivo, que atua em saúde, ensino, cultura, pesquisa e meio ambiente.",""],"1sflkm2":["É a Lei 9.790/1999: a qualificação como OSCIP é dada pelo Ministério da Justiça e é ato vinculado.",""],"glme3g":["É a Lei 13.019/2014: termo de COLABORAÇÃO = proposta da Administração; termo de FOMENTO = proposta da organização da sociedade civil. Os dois envolvem repasse de recursos.",""],"18zxi1c":["É o art. 2º, VIII-A, da Lei 13.019/2014.",""],"1tvbl91":["SESI, SENAI, SESC e afins são entidades paraestatais privadas. Recebem contribuições e prestam contas ao TCU, mas não precisam fazer concurso público (STF, RE 789.874).",""],"dgrn0t":["Há vinculação e controle finalístico (tutela), previsto em lei.",""],"au1upb":["Desconcentração: criação de órgão dentro da mesma pessoa.","",["Descentralização passa a atividade para outra pessoa.","Correta.","Delegação passa a execução a particular.","Outorga cria entidade da indireta.","Concessão é contrato com particular."]],"68x7d6":["Autarquia (art. 37, XIX).","",["Empresa pública é de direito privado.","Sociedade de economia mista é de direito privado.","Correta.","Fundação privada não integra o Estado.","OS é entidade privada."]],"arbraj":["Sociedade anônima, obrigatoriamente.","",["Qualquer forma é a empresa pública.","Não pode ser limitada.","Correta.","Não é cooperativa.","Não é associação."]],"11i8c7p":["Termo de parceria (Lei 9.790/1999).","",["Contrato de gestão é da OS.","Correta.","Termo de fomento é do MROSC.","Convênio é entre entes.","Concessão é de serviço público."]],"x11jjj":["Contrato de gestão (Lei 9.637/1998).","",["Correta.","Termo de parceria é da OSCIP.","Acordo de cooperação é do MROSC.","Permissão é de serviço público.","Autorização é ato precário."]],"hqcc0s":["Decreto, após contrato de gestão.","",["Não é por lei.","Correta.","Não é por resolução do Senado.","Não é por portaria.","Não é por emenda."]],"1vxo2p":["5 anos, vedada a recondução.","",["Não é 2 anos e não há recondução.","4 anos era o regime antigo de várias agências.","Correta.","6 anos não é o prazo.","O mandato é fixo."]],"1t1pqw7":["Serviço social autônomo (Sistema S), que é paraestatal.","",["Integra.","Integra.","Integra.","Integra.","Correta."]],"145s2xj":["Titularidade e execução, por lei.","",["Só a execução é a delegação.","Correta.","Não é só a fiscalização.","Não é só o patrimônio.","Há transferência."]],"1yegaq8":["Consórcio público de direito público.","",["OS é entidade privada.","OSCIP é entidade privada.","Correta.","Empresa pública é estatal.","Sociedade de economia mista é estatal."]],"mn3gni":["Controle finalístico (tutela).","",["Não há hierarquia.","Correta.","Não há subordinação.","Há controle.","Delegação é para particular."]]},"poderes":{"10n3xdl":["A multa de trânsito é PODER DE POLÍCIA: atinge qualquer pessoa, sem vínculo especial com a Administração. O poder disciplinar só alcança quem tem vínculo especial: servidores, contratados, alunos de escola pública e afins.","Pergunte: a pessoa tem vínculo especial com a Administração? Sim = disciplinar. Não (vínculo geral) = polícia."],"18yo0dc":["É o art. 13: não se delegam a edição de atos normativos, a decisão de recursos administrativos e as matérias de competência exclusiva.","Macete \"CE-NO-RE\": Competência Exclusiva, atos NOrmativos, REcursos."],"11x6502":["É vício de finalidade, também chamado de desvio de poder.",""],"1jhfsj7":["É o art. 13, II, da Lei 9.784.",""],"o15ypp":["O art. 12 da Lei 9.784 permite delegar mesmo a órgão ou titular que NÃO seja hierarquicamente subordinado, quando conveniente por razões técnicas, sociais, econômicas, jurídicas ou territoriais.",""],"14ein9e":["No Tema 532 (RE 633.782), o STF decidiu que a ORDEM de polícia (a criação das normas e limites, feita por lei) não pode ser delegada. As fases de consentimento, fiscalização e sanção podem ser delegadas a estatais de capital majoritariamente público que prestem serviço público exclusivo, sem concorrência.",""],"1fs46d3":["A Administração aplica a multa sozinha, mas, se o particular não paga, não pode tomar o dinheiro à força: precisa inscrever em dívida ativa e propor execução fiscal no Judiciário.",""],"12ejkuj":["É o art. 84, VI, b, da CF: o Presidente extingue por decreto funções ou cargos públicos VAGOS. Cargo ocupado só se extingue por lei.",""],"1es5e4o":["Os poderes servem para alcançar o interesse público (são instrumentos) e o agente é obrigado a exercê-los. Por isso são irrenunciáveis, e a omissão também pode ser abuso.",""],"1uglfsw":["A lei define todos os elementos do ato. Preenchidos os requisitos, o agente é obrigado a agir de um único modo. Exemplo: conceder aposentadoria compulsória aos 75 anos.",""],"8w9wr4":["A margem de escolha (mérito) existe dentro dos limites da lei. Discricionariedade não é arbitrariedade: o ato continua sujeito a razoabilidade e proporcionalidade.",""],"r7gjae":["O poder hierárquico organiza a relação de subordinação entre órgãos e agentes de uma mesma pessoa jurídica.",""],"fhfb8n":["São pessoas jurídicas diferentes. Há vinculação e controle finalístico (tutela), não hierarquia.",""],"1m5vac4":["É o art. 12.",""],"nsqvlb":["É o art. 13 da Lei 9.784.",""],"x2wven":["É o art. 14, §2º. O ato deve indicar as matérias e poderes transferidos, os limites e a duração, e ser publicado no meio oficial.",""],"x2y54l":["É o art. 14, §3º: quem responde pelo ato é o delegado. É também contra ele que se impetra mandado de segurança (Súmula 510 do STF).",""],"7lrmit":["É o art. 15 da Lei 9.784: o superior chama para si a competência do subordinado, temporariamente, por motivos relevantes devidamente justificados.",""],"1zp68k":["Alcança quem tem vínculo especial com a Administração. A apuração exige contraditório e ampla defesa.",""],"1xt0wx9":["O contratado tem vínculo especial com a Administração (o contrato). Por isso a sanção por inexecução contratual é poder disciplinar, e não de polícia.",""],"a23hea":["É o art. 143 da Lei 8.112: a apuração é obrigatória, por sindicância ou PAD. Não apurar pode configurar condescendência criminosa (CP, art. 320).",""],"11k5270":["É o art. 84, IV, da CF: o decreto regulamentar detalha a lei para que ela possa ser aplicada.",""],"gn2us9":["Ele atua \"secundum legem\" (segundo a lei): explica e detalha, mas não pode criar direitos ou obrigações novas. Se for além, o Congresso pode sustá-lo (art. 49, V).",""],"14igu32":["É o art. 84, VI, a: organização e funcionamento, desde que sem aumento de despesa e sem criação ou extinção de órgãos. É a única hipótese de decreto que inova diretamente com base na CF.",""],"jk2knr":["É o art. 49, V, da CF, por decreto legislativo.",""],"197zgaf":["É o art. 78 do CTN. O conceito está no CTN porque o exercício do poder de polícia justifica a cobrança de taxa (art. 145, II, da CF).",""],"7we6sp":["Macete \"DAC\". A discricionariedade é a regra, mas há atos de polícia vinculados, como a licença para construir.",""],"1hilnwa":["Preenchidos os requisitos legais, a Administração é obrigada a conceder. É exemplo da fase de consentimento.",""],"1cnv5om":["Ordem (a lei fixa os limites), consentimento (licença ou autorização), fiscalização (verificar o cumprimento) e sanção (punir quem descumpre). Exemplo no trânsito: o CTB, a CNH, o radar e a multa.",""],"myvb3a":["É o Tema 532 (RE 633.782), que envolvia a BHTRANS. Só a fase de ordem é indelegável.",""],"4e4ya0":["A ordem de polícia é indelegável. Ela nasce da lei, que só o Estado edita.",""],"1fz17nw":["Depende de inscrição em dívida ativa e execução fiscal.",""],"1gvgh9e":["A polícia administrativa é preventiva e regida pelo direito administrativo (fiscalização sanitária, trânsito). A polícia judiciária é repressiva, investiga crimes e é regida pelo processo penal (Polícia Civil, Polícia Federal).",""],"zctt72":["É o art. 1º da Lei 9.873/1999: 5 anos contados do fato ou, na infração permanente ou continuada, do dia em que cessou. Se o fato também for crime, vale o prazo penal.",""],"1k8cf8s":["Excesso: o agente vai além da sua competência. Desvio: o agente é competente, mas busca outro fim. As duas espécies são abuso de poder.",""],"1cx7vq5":["É vício de competência. Exemplo: o fiscal que interdita o estabelecimento quando só podia autuar.",""],"1w5qq5p":["Como os poderes são poderes-deveres, deixar de agir quando a lei obriga é abuso por omissão e pode ser corrigido por mandado de segurança.",""],"1m05y6r":["O superior chamar para si a competência do subordinado (art. 15).","",["Isso é delegação.","Correta.","Isso é anulação.","Isso é poder disciplinar.","Isso é poder regulamentar."]],"1qrd8hn":["Art. 13, II: a decisão de recursos administrativos.","",["Pode ser delegada.","Correta.","Pode ser delegada.","Pode ser delegada.","Pode ser delegada."]],"1xzaebh":["De polícia: o restaurante não tem vínculo especial com a Administração.","",["Hierárquico é entre órgãos e agentes.","Disciplinar exige vínculo especial.","Correta.","Regulamentar é editar decretos.","Vinculado é forma de atuar, e a pergunta é sobre a espécie de poder."]],"1pzgi93":["Disciplinar: o servidor tem vínculo especial.","",["Polícia é sobre particulares em geral.","Correta.","Regulamentar é editar decretos.","Normativo é editar normas.","Tributário não é poder administrativo."]],"1l2hzko":["Desvio de finalidade: a remoção não é penalidade.","",["O prefeito é competente; não há excesso.","Correta.","Não é regular.","Avocação é chamar competência.","Delegação é transferir competência."]],"1a5eoef":["Ordem de polícia.","",["Pode ser delegada.","Pode ser delegada.","Pode ser delegada.","Correta.","Existe uma fase indelegável."]],"x4jjkk":["Criar órgãos públicos (art. 84, VI, a).","",["Pode extinguir cargos vagos.","Pode, sem aumento de despesa.","Correta.","Pode reorganizar.","Há uma alternativa correta."]],"13qfm7w":["Lei 9.873/1999: 5 anos.","",["1 ano não é o prazo.","2 anos não é o prazo.","3 anos é a prescrição intercorrente (processo parado).","Correta.","10 anos não é o prazo."]],"rbkl1d":["Excesso de poder.","",["Desvio é fim diverso com competência.","Correta.","Não é omissão.","Autotutela é rever os próprios atos.","Discricionariedade é margem legal de escolha."]],"4vylfu":["Autoexecutoriedade.","",["Tipicidade é a correspondência com figura legal.","Imperatividade é impor obrigação.","Correta.","Presunção é considerar o ato válido.","Discricionariedade é margem de escolha."]],"1ts9ane":["Congresso Nacional (art. 49, V).","",["O STF controla constitucionalidade.","Correta.","O TCU susta atos, não regulamentos.","O Presidente é quem edita.","Não é o Senado sozinho."]],"8ct5sx":["Poderes-deveres irrenunciáveis.","",["Não são renunciáveis.","Correta.","Não são pessoais.","Não são opcionais.","São administrativos."]]},"processo-adm":{"1c2u5w8":["É o art. 59 da Lei 9.784: 10 dias, contados da ciência ou da divulgação oficial da decisão. O recurso deve ser decidido em até 30 dias, prorrogáveis por igual período.","Recurso = 10 dias para recorrer, 5 dias para a autoridade reconsiderar, 30 dias para decidir."],"14ngkm3":["O art. 65, parágrafo único, proíbe o agravamento na REVISÃO. A revisão serve para beneficiar quem foi punido. Já no RECURSO, o agravamento é possível (art. 64, parágrafo único).","Recurso pode piorar (com aviso prévio). Revisão nunca piora."],"dv0vo9":["É o art. 24, §1º, III, da Lei 12.527: reservada = 5 anos; secreta = 15 anos; ultrassecreta = 25 anos (renovável uma vez).",""],"1fi1g24":["É o art. 59 da Lei 9.784.",""],"1fgzd6s":["É vedado (art. 65, parágrafo único).",""],"1pgedfh":["É a Súmula Vinculante 21: exigir depósito ou arrolamento de bens para recorrer fere o direito de petição e a ampla defesa. O recurso administrativo é, em regra, gratuito.",""],"12cyl3y":["Amizade íntima ou inimizade notória é SUSPEIÇÃO (art. 20), que pode ser alegada pelo interessado. Impedimento (art. 18) é objetivo: interesse na matéria, ter atuado como perito ou testemunha, ou estar em litígio com o interessado.","Impedimento = fato objetivo, a autoridade deve se afastar. Suspeição = relação pessoal (amizade, inimizade), pode ser arguida."],"1egkzc9":["É o art. 24, §1º, I. O prazo pode ser prorrogado uma única vez, por igual período (art. 35, §1º, III).",""],"1i16358":["É o art. 1º: vale para a Administração federal direta e indireta.",""],"1q0trbl":["É o art. 1º, §1º: quando esses Poderes atuam em função administrativa (contratar, gerir pessoal), seguem a lei.",""],"dwhawv":["É o art. 69: o PAD da Lei 8.112 e o processo tributário, por exemplo, seguem suas leis, e a Lei 9.784 só completa o que faltar.",""],"lc1e94":["É a Súmula 633 do STJ, especialmente quanto ao prazo de 5 anos para anular atos (art. 54), quando não houver lei local própria.",""],"aghbvk":["É o art. 3º, IV: o advogado é facultativo, salvo quando a lei o tornar obrigatório. No PAD, a SV 5 diz que a falta de defesa técnica não ofende a Constituição.",""],"132x46":["É o art. 5º. O pedido deve ser, em regra, por escrito (art. 6º).",""],"9453z":["É o art. 10: ressalvada previsão especial em ato normativo próprio.",""],"14ano5j":["É o art. 18, I. Também está impedido quem participou ou vai participar como perito, testemunha ou representante, ou cujo cônjuge ou parente até o 3º grau esteja nessa situação, e quem litiga com o interessado.",""],"16663sb":["É o art. 20: com os interessados ou seus cônjuges, companheiros, parentes e afins até o 3º grau. O indeferimento da suspeição pode ser objeto de recurso, sem efeito suspensivo (art. 21).",""],"w56ksc":["É o art. 19: a autoridade deve se abster de atuar e comunicar o impedimento. Deixar de comunicar é falta grave para fins disciplinares.",""],"9lcikj":["É o art. 24: 5 dias, prorrogáveis até o dobro (10 dias) mediante justificativa.",""],"1m8kqcn":["É o art. 26, §2º. A intimação feita sem observar a lei é nula, mas o comparecimento do administrado supre a falta (§5º).",""],"fai61l":["É o art. 49: 30 dias, prorrogáveis por igual período, com motivação expressa. A Administração tem o dever de decidir (art. 48).",""],"8agq5a":["É o art. 56: no recurso administrativo pode-se discutir tanto a legalidade quanto a conveniência e oportunidade, ao contrário do controle judicial.",""],"1oys0cn":["É o art. 56, §1º: a autoridade que decidiu pode reconsiderar em 5 dias; se não reconsiderar, manda o recurso para a autoridade superior.",""],"vnzi9w":["É o art. 57, salvo disposição legal diversa.",""],"1ombdi1":["É o art. 59.",""],"kg03ua":["É o art. 59, §1º: 30 dias, prorrogáveis por igual período ante justificativa explícita (§2º).",""],"bz2oyj":["É o art. 61. Havendo receio de prejuízo de difícil reparação, a autoridade pode dar efeito suspensivo, de ofício ou a pedido (parágrafo único).",""],"yj3vto":["É o art. 64, parágrafo único: a chamada \"reformatio in pejus\" é permitida no recurso administrativo, mas o recorrente deve ser avisado antes para se manifestar.",""],"13sxu4e":["É o art. 65: a pedido ou de ofício, quando surgirem fatos novos ou circunstâncias relevantes que mostrem que a sanção foi inadequada.",""],"s1rkda":["É o art. 65, parágrafo único.",""],"1awvey":["É a Súmula Vinculante 21.",""],"10j62s3":["É o art. 69-A: também têm prioridade a pessoa com deficiência e a portadora de doença grave.",""],"ha2bxq":["É o art. 10, §3º, da Lei 12.527: é proibido exigir os motivos do pedido de informação de interesse público.",""],"j0apk1":["É o art. 11, §§1º e 2º: 20 dias, prorrogáveis por mais 10, com justificativa ao requerente.",""],"1k49bnq":["É o art. 24, §1º, I.",""],"1twdsnx":["É o art. 24, §1º, II e III.","Reservada 5, secreta 15, ultrassecreta 25."],"8l7625":["É o art. 31, §1º, I, da LAI: independentemente de classificação, por até 100 anos a contar da produção.",""],"n21kva":["É o art. 8º, §4º, da LAI: ficam dispensados da divulgação ativa na internet, mas continuam obrigados a divulgar em tempo real a execução orçamentária e financeira (LC 101/2000, art. 73-B).",""],"14293ij":["São os arts. 7º, III, e 23 da Lei 13.709/2018: a execução de políticas públicas e o cumprimento de competências legais são bases legais próprias, que dispensam o consentimento.",""],"16rd612":["A LGPD tem várias bases legais além do consentimento, inclusive a execução de políticas públicas pela Administração (art. 7º, III).",""],"1wh6gmi":["Art. 59: 10 dias.","",["5 dias é o prazo da reconsideração.","Correta.","15 dias não é o prazo.","30 dias é o prazo para decidir.","60 dias não é o prazo."]],"e5x2pj":["Art. 56, §1º: 5 dias.","",["Não é 48 horas.","Correta.","10 dias é o prazo do recurso.","15 dias não é o prazo.","30 dias é o prazo para decidir."]],"1id2nz3":["Art. 57: 3 instâncias.","",["Não é uma só.","Não são duas.","Correta.","Quatro passam do limite.","Há limite."]],"xz4pr6":["Art. 65, parágrafo único: não pode agravar a sanção.","",["Quem pode agravar é o recurso.","Correta.","Cabe a qualquer tempo.","Não exige depósito.","É administrativa."]],"1mi08gz":["Art. 20: suspeição.","",["Impedimento é situação objetiva (art. 18).","Correta.","Não gera nulidade absoluta automática.","Não tem relação com prescrição.","Não tem relação com decadência."]],"1q2u7fi":["Art. 49: 30 dias.","",["10 dias é o recurso.","15 dias não é o prazo.","Correta.","60 dias só com prorrogação.","90 dias não é o prazo."]],"fnm74z":["Vedação do depósito prévio para recurso administrativo.","",["Correta.","Defesa técnica no PAD é a SV 5.","Nepotismo é a SV 13.","Não trata de prescrição.","Não trata de imunidade."]],"i2vymv":["Art. 11: 20 dias, prorrogáveis por 10.","",["5 dias não é o prazo.","10 dias é só a prorrogação.","Correta.","30 dias é o total com prorrogação, não o prazo inicial.","60 dias não é o prazo."]],"1ji2s32":["LAI, art. 24: 15 anos.","",["5 anos é a reservada.","10 anos não é prazo da LAI.","Correta.","25 anos é a ultrassecreta.","100 anos é a informação pessoal."]],"1wfnls4":["Art. 10, §3º: dispensa motivação.","",["Não exige motivação.","Correta.","Não exige advogado.","O serviço de busca é gratuito, em regra.","Qualquer interessado pode pedir."]],"cv3nus":["Subsidiariamente (Súmula 633 do STJ).","",["Aplica-se, sim.","Correta.","Não substitui a lei local.","Vale também para Municípios.","Vale para todos os Municípios."]]},"responsabilidade":{"s8sp51":["Pelo art. 37, §6º, da CF, o Estado responde sem que a vítima precise provar culpa (responsabilidade objetiva). Mas, diferente do risco integral, o Estado pode se livrar ou reduzir a indenização provando culpa exclusiva da vítima, caso fortuito, força maior ou fato exclusivo de terceiro.","Risco administrativo = admite excludentes (regra). Risco integral = não admite (exceção: dano nuclear, ambiental)."],"1ys1oko":["No Tema 940 (RE 1.027.633), o STF fixou a tese da dupla garantia: a vítima processa o Estado ou a prestadora de serviço público, e não o agente. Depois, o Estado cobra do agente em ação regressiva, se houver dolo ou culpa.",""],"x7hf1a":["No Tema 130 (RE 591.874), o STF decidiu que a responsabilidade objetiva da concessionária vale tanto para o usuário do serviço quanto para o terceiro não usuário. Exemplo: ônibus que atropela um pedestre.",""],"cixf3y":["Essa é a diferença em relação ao risco integral, em que não há excludentes.",""],"nqwhex":["Tema 940: a ação é contra o Estado ou a prestadora. O agente só responde perante o Estado, regressivamente.",""],"5s5sij":["É o art. 21, XXIII, d, da CF: a responsabilidade civil por danos nucleares independe da existência de culpa, e a doutrina majoritária entende que nem as excludentes a afastam.",""],"1kzn1dz":["O art. 37, §6º, garante o regresso só \"nos casos de dolo ou culpa\": a responsabilidade do agente é SUBJETIVA. O Estado precisa provar que o agente agiu com dolo ou culpa.",""],"1mvc1c":["É o Tema 897 do STF.",""],"14gn33k":["É o art. 37, §6º, da CF: União, Estados, Municípios, autarquias e também concessionárias, permissionárias e estatais que prestam serviço público.",""],"dijk9s":["A vítima não precisa provar culpa do agente. Basta provar a conduta estatal, o dano e o nexo de causalidade.",""],"bimghy":["São os três elementos. A culpa fica de fora.",""],"1a2l2g0":["É o art. 37, §6º, parte final: a responsabilidade do agente perante o Estado é subjetiva.",""],"4b5l7r":["Todas essas excludentes rompem o nexo causal entre a atuação do Estado e o dano.",""],"ouhg5w":["Quando a vítima também contribuiu para o dano, a indenização é reduzida na proporção da culpa dela. Não exclui, só diminui.",""],"1vbgn0b":["Basta o dano e a ligação com a atividade. O Estado responde mesmo com caso fortuito ou culpa da vítima.",""],"1n1zqks":["É o art. 21, XXIII, d, da CF.",""],"fi0bih":["O STJ aplica o risco integral ao dano ambiental (arts. 225, §3º, da CF e 14, §1º, da Lei 6.938/1981): o poluidor não pode alegar excludentes.",""],"19z0saf":["É o Tema 940 (tese da dupla garantia): garante a vítima, que processa quem tem dinheiro e responde objetivamente, e garante o agente, que só responde perante o Estado.",""],"1cofiz0":["O STF não admite (Tema 940). A ação é contra o Estado ou a prestadora.",""],"1gilqup":["O art. 37, §6º, só alcança as prestadoras de SERVIÇO PÚBLICO. A estatal que explora atividade econômica (como um banco estatal) responde pelas regras do direito civil e do consumidor (CF, art. 173, §1º, II).",""],"1gzz0hk":["O Estado responde quando o dano tem relação com a função, mesmo fora do expediente. Exemplo: policial de folga que usa a arma da corporação. Se o dano não tem ligação com a função, o Estado não responde.",""],"tt58j3":["Na omissão genérica, a vítima precisa provar que o serviço não funcionou, funcionou mal ou atrasou (culpa anônima do serviço, \"faute du service\"). Na omissão específica, quando o Estado tinha dever de agir naquele caso, a jurisprudência aplica a responsabilidade objetiva.",""],"heynbc":["No Tema 592 (RE 841.526), o STF decidiu que o Estado responde pela morte do preso quando descumpre o seu dever específico de proteção (CF, art. 5º, XLIX), salvo se provar que não podia evitar a morte.",""],"glmi6q":["No Tema 362 (RE 608.880), o STF exigiu nexo causal direto entre a fuga e o crime. Se o crime ocorre muito tempo depois, sem ligação com a fuga, o Estado não responde.",""],"yziqga":["O aluno está sob a guarda do Estado. Há dever específico de proteção, e por isso a responsabilidade é objetiva.",""],"1q04cwm":["A lei geral e abstrata não gera indenização. As exceções são a lei de efeitos concretos (que atinge pessoas determinadas, como uma lei que cria parque sobre terreno específico) e a lei declarada inconstitucional que causou dano.",""],"39xhdc":["É o art. 5º, LXXV, da CF. Fora dessas hipóteses, atos judiciais em regra não geram responsabilidade do Estado, salvo dolo ou fraude do juiz.",""],"1f15wh0":["É o Decreto 20.910/1932 (art. 1º): o STJ aplica 5 anos, e não o prazo de 3 anos do Código Civil, por ser regra especial (Tema 553 do STJ).",""],"1lcs314":["É o Tema 666 do STF (RE 669.069): exemplo clássico é o acidente de trânsito causado por um particular contra um veículo público.",""],"g7te9x":["A responsabilidade objetiva só dispensa a prova da CULPA. Dano e nexo precisam ser provados.",""],"1tifyko":["É o RE 591.874 (Tema 130 do STF).",""],"ut0rk1":["A evolução foi: irresponsabilidade, teorias civilistas (culpa), culpa do serviço, risco administrativo. O Brasil nunca adotou a irresponsabilidade nas Constituições.",""],"10j268m":["A regra é o risco administrativo (art. 37, §6º). O risco integral é exceção (dano nuclear, ambiental).",""],"1977x2t":["Se o dano decorre só da conduta da vítima (por exemplo, quem se joga na frente do trem), o Estado não responde.",""],"svxys9":["O \"simples fato da obra\" (o dano decorre da própria existência da obra, como rachaduras em imóvel vizinho) gera responsabilidade objetiva do Estado. Se o dano for causado por culpa do empreiteiro na execução, a empreiteira responde, e o Estado pode responder subsidiariamente.",""],"1lg5z9i":["É ônus do Estado, porque a responsabilidade do agente é subjetiva.",""],"clsokl":["É o art. 37, §6º: concessionárias de energia, água, transporte e telefonia respondem como o Estado.",""],"18fq4f4":["Art. 37, §6º: risco administrativo.","",["Risco integral é exceção.","Correta.","Culpa do serviço é aplicada a omissões genéricas, não é a regra.","Foi superada.","A culpa civil vale para o agente, não para o Estado."]],"1hglwnw":["Art. 37, §6º: dolo ou culpa.","",["O nexo sozinho não basta.","Correta.","O dano sozinho não basta.","Exige-se dolo ou culpa.","Risco integral não se aplica ao agente."]],"3605i2":["A culpa do agente não exclui: ela é o fundamento do regresso.","",["É excludente.","É excludente.","É excludente.","É excludente.","Correta."]],"1jvkvs8":["Nuclear (art. 21, XXIII, d).","",["Trânsito segue o risco administrativo.","Correta.","Omissão genérica é culpa do serviço.","Foragido exige nexo direto.","Ato legislativo, em regra, não gera indenização."]],"163q5w0":["O Estado ou a prestadora de serviço público.","",["Não pode processar o agente diretamente.","Correta.","Não há litisconsórcio obrigatório.","O MP não é réu.","O TCU não é réu."]],"vg9wdq":["Decreto 20.910/1932: 5 anos.","",["3 anos é o prazo do Código Civil, afastado.","Correta.","10 anos não é o prazo.","20 anos era do CC antigo.","É prescritível."]],"13nm3z":["Imprescritível (Tema 897).","",["Não prescreve.","8 anos é a ação de improbidade, não o ressarcimento.","Correta.","Não prescreve.","Não é decadencial."]],"g3crpe":["Reduz a indenização.","",["Excluir é a culpa exclusiva.","Correta.","Não dobra.","Tem efeito.","Não transfere."]],"cx5e3q":["Objetiva do Estado (Tema 592).","",["Gera responsabilidade.","Correta.","O Estado responde.","A família é vítima.","Há responsabilidade civil."]],"uh7vee":["Pelo regime de direito privado.","",["O art. 37, §6º, é para prestadoras de serviço público.","Correta.","Responde.","Não se aplica risco integral.","A empresa responde."]],"e23n3y":["Culpa.","",["O dano deve ser provado.","O nexo deve ser provado.","Correta.","A conduta deve ser provada.","Não dispensa tudo."]],"19zgqma":["Art. 5º, LXXV.","",["Correta.","O 37, §6º, é a regra geral.","O 100 trata de precatórios.","O 144 trata de segurança pública.","O 225 trata de meio ambiente."]]},"servicos-publicos":{"axx9hn":["É o art. 37 da Lei 8.987/1995: a concessionária não fez nada de errado, mas o poder concedente quer retomar o serviço. Por isso exige lei autorizativa específica e indenização PRÉVIA.","Encampação = interesse público (lei + indenização prévia). Caducidade = culpa da concessionária (decreto). Rescisão = culpa do poder concedente (ação judicial)."],"1pmrnz":["Caducidade é a extinção por inadimplemento da CONCESSIONÁRIA (art. 38). Extinção por interesse público, sem culpa da concessionária, é encampação (art. 37).",""],"152veow":["É o art. 6º, §3º, II, da Lei 8.987: o corte por falta de pagamento é permitido, desde que haja aviso prévio e se considere o interesse da coletividade.",""],"rg0jsa":["É o art. 37 da Lei 8.987.",""],"1krzfnk":["Quando é a concessionária que pede a extinção por falta do poder concedente, trata-se de RESCISÃO, que exige ação judicial (art. 39). Caducidade é a extinção por falta da concessionária.",""],"bxcfmz":["É o art. 2º, §4º, I, da Lei 11.079/2004 (valor atualizado pela Lei 13.529/2017; antes eram R$ 20 milhões).",""],"p15utk":["A permissão pode ser dada a pessoa física OU jurídica (art. 2º, IV). Quem só aceita pessoa jurídica ou consórcio é a concessão (art. 2º, II).","Concessão = só pessoa jurídica ou consórcio. Permissão = pessoa física ou jurídica."],"19x472j":["É o RE 591.874 (Tema 130 do STF): o art. 37, §6º, não distingue usuário de não usuário.",""],"z8zxjn":["É o art. 175 da CF: a delegação de serviço público por concessão ou permissão sempre exige licitação.",""],"si5d4d":["É a descentralização por delegação (colaboração): o particular só executa. O Estado continua titular, fiscaliza e pode retomar o serviço.",""],"1aqn5jo":["É o art. 6º, §1º, da Lei 8.987.",""],"1vagwwi":["É o art. 6º, §3º, caput: em emergência, a interrupção pode ser feita sem aviso prévio.",""],"qq0dxc":["É o art. 6º, §3º, II.",""],"1n1kgh8":["É o art. 6º, §4º, da Lei 8.987 (incluído pela Lei 14.015/2020): o corte não pode começar na sexta, no sábado, no domingo, em feriado ou na véspera de feriado.",""],"40otj2":["É o art. 2º, II: por licitação (concorrência ou diálogo competitivo), por prazo determinado, a quem demonstre capacidade.",""],"1mpq1jy":["É o art. 2º, IV: por licitação, a quem demonstre capacidade, por sua conta e risco.",""],"170jmzd":["A concessão só pode ser dada a pessoa jurídica ou consórcio de empresas (art. 2º, II).",""],"qh1xyb":["É o art. 40 da Lei 8.987: contrato de adesão, que destaca a precariedade e a revogabilidade unilateral pelo poder concedente.",""],"vm7r8q":["É o art. 37 da Lei 8.987.",""],"1d3wt3j":["É o art. 37.",""],"1b96ru8":["É o art. 38: serviço inadequado, descumprimento de cláusulas, paralisação, perda de condições, não pagamento de multas, entre outros.",""],"om7ye6":["É o art. 38, §§2º a 4º: a concessionária é avisada e recebe prazo para corrigir as falhas; comprovada a inadimplência, a caducidade é declarada por decreto, sem indenização prévia.",""],"xpezq8":["É o art. 38, §§4º e 5º: indenização só pelos bens reversíveis ainda não amortizados, descontados multas e danos.",""],"1bdj3e3":["É o art. 39: a concessionária não pode simplesmente parar o serviço; precisa entrar com ação judicial.",""],"dj10j5":["É o art. 39, parágrafo único: aplicação do princípio da continuidade do serviço público.",""],"b17zi2":["É o art. 35, §1º: os bens necessários ao serviço voltam ao poder concedente, para que ele continue o serviço.",""],"1a6nlr0":["É o art. 2º, §1º, da Lei 11.079: o usuário paga tarifa e o Estado complementa. Exemplo: rodovia com pedágio mais pagamento público.",""],"c7hwfl":["É o art. 2º, §2º: não há tarifa do usuário; quem paga é a Administração. Exemplo: construção e gestão de presídio ou hospital.","Patrocinada = tarifa + dinheiro público. Administrativa = só dinheiro público."],"1rb7t0v":["É o art. 2º, §4º, I, da Lei 11.079.",""],"1q1r3g2":["É o art. 5º, I, da Lei 11.079.",""],"7awowj":["É o art. 2º, §4º, III: a PPP tem que envolver a prestação de um serviço. Só obra, só equipamento ou só mão de obra não cabem.",""],"o2rwu9":["É o art. 9º da Lei 11.079: a SPE implanta e gere o objeto da parceria. A Administração não pode ser dona da maioria do capital votante dela (§4º).",""],"17ctr6b":["É o RE 591.874 (Tema 130 do STF).",""],"1jsaive":["Não dá para medir quanto cada um usa. Exemplos: iluminação pública, segurança pública. São custeados por impostos (ou pela contribuição de iluminação pública, art. 149-A da CF).",""],"9kiefd":["Cada usuário tem consumo medido. Podem ser cobrados por tarifa ou taxa. Exemplos: água, energia, telefone.",""],"jir6rn":["A Lei 14.133 alterou o art. 2º, II, da Lei 8.987, incluindo o diálogo competitivo ao lado da concorrência.",""],"72oaza":["A extinção por falta da concessionária é a CADUCIDADE (art. 38). A encampação é por interesse público (art. 37).",""],"1wuk56r":["É o art. 9º da Lei 8.987: a tarifa é preservada pelas regras de revisão da lei, do edital e do contrato, garantindo o equilíbrio econômico-financeiro.",""],"hxsxvz":["Encampação (art. 37).","",["Caducidade é por falta da concessionária.","Correta.","Rescisão é por falta do poder concedente.","Anulação é por ilegalidade.","Reversão é o retorno dos bens."]],"hrgosw":["Caducidade (art. 38).","",["Encampação é por interesse público.","Correta.","Rescisão é por falta do poder concedente.","Advento do termo é o fim do prazo.","Revogação não é termo da Lei 8.987 para concessão."]],"h72815":["Ação judicial (art. 39).","",["Decreto é da caducidade.","Correta.","Lei específica é da encampação.","O TCU não participa.","Não há referendo."]],"i5idf4":["Pessoa física ou jurídica (art. 2º, IV).","",["Pessoa jurídica só é exigida na concessão.","Consórcio é possível na concessão.","Correta.","Não é só estatal.","Não é só ONG."]],"12t6jjn":["R$ 10 milhões.","",["R$ 1 milhão é pouco.","R$ 5 milhões é pouco.","Correta.","R$ 20 milhões era o valor antigo.","R$ 50 milhões não é o mínimo."]],"12ms4p8":["Art. 5º, I: 35 anos.","",["20 anos não é o prazo.","25 anos não é o prazo.","30 anos não é o prazo.","Correta.","50 anos passa do limite."]],"2hr4d4":["A Administração é usuária direta ou indireta.","",["Só tarifa é concessão comum.","Correta.","Há contraprestação pública.","Exige licitação.","O prazo é de 5 a 35 anos."]],"gcx3n0":["Lei autorizativa específica e indenização prévia.","",["Decreto e indenização posterior é a caducidade.","Correta.","Ação judicial é a rescisão.","Não depende de acordo.","Não depende do TCU."]],"f837kw":["A gratuidade universal não consta da lei.","",["Consta.","Consta.","Consta: a lei fala em modicidade, não gratuidade.","Correta.","Consta."]],"2k4di4":["Uti universi.","",["Uti singuli tem usuário determinado.","Correta.","É serviço público.","Pode ser prestado diretamente.","É serviço essencial."]],"144247c":["Objetiva (RE 591.874).","",["Não é subjetiva.","Correta.","Existe.","A concessionária responde diretamente.","Há responsabilidade civil."]],"1t99gwz":["Sociedade de propósito específico (art. 9º).","",["Consórcio público é entre entes.","Correta.","Não é fundação.","Não é autarquia.","Não é OS."]]}};
